/**
 * TemplateTab — renders ONE template tab (e.g. "General", "Appearance")
 * generically as a column layout. The tab owns a range of columns
 * (`tab.columns`); every section with `column ∈ tab.columns` lands in the
 * matching column (sorted by column, then by row). No hardcoding —
 * everything comes from the template.
 *
 * Loads the three stores ONCE (profile/config/status_effects) and saves every
 * field into the right one (like TemplateSectionForm, but for a whole tab).
 *
 * Multiline text fields carrying {tokens} get a **live preview of the
 * replacements** from the backend (POST /characters/{name}/resolve-tokens) —
 * never a frontend re-implementation.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useI18n } from '../I18nProvider'
import { apiGet, apiPost } from '../api'
import { useCharacterFormHost } from './CharacterFormHost'
import { useToast } from '../Toast'
import { Field } from './Field'
import { TemplateField, tmplText, type TmplFieldDef, type DynamicData } from './TemplateField'
import type { TmplSection } from './TemplateSectionForm'
import { FieldImage } from './FieldImage'

const FORCE_READONLY = new Set(['character_name'])

interface TmplTabDef {
  id: string
  label?: string
  label_de?: string
  columns?: number[]
}
export interface TmplSectionRaw extends TmplSection {
  special?: unknown
  column?: number
  row?: number
  /** The section takes whatever height its column has left over — for slots
   *  whose content scales (a picture), not for stacked fields. */
  grow?: boolean
}

function asBoolStore(f: TmplFieldDef) {
  return f.store === 'config' ? 'config' : f.store === 'status_effects' ? 'status_effects' : 'profile'
}

interface TokenChip {
  token: string
  label: string
}

// Collects the {token} placeholders the template aims at `targetKey`
// (replacement.target == targetKey, a string or a list) — across ALL sections,
// because e.g. {gender} comes from another column.
export function collectTokens(sections: TmplSectionRaw[], targetKey: string, lang: string): TokenChip[] {
  const out: TokenChip[] = []
  const seen = new Set<string>()
  for (const s of sections) {
    for (const f of s.fields || []) {
      const r = f.replacement as { token?: string; target?: string | string[] } | undefined
      if (!r) continue
      const targets = Array.isArray(r.target) ? r.target : r.target ? [r.target] : []
      if (!targets.includes(targetKey)) continue
      const tok = String(r.token || f.key)
      if (!tok || seen.has(tok)) continue
      seen.add(tok)
      out.push({ token: tok, label: tmplText(f, 'label', lang) || tok })
    }
  }
  return out
}

// A multiline text field with a live token preview (resolved by the backend)
// and clickable token chips that insert {placeholder} at the caret.
function PromptField({
  character,
  field,
  value,
  disabled,
  tokens,
  onCommit,
}: {
  character: string
  field: TmplFieldDef
  value: unknown
  disabled?: boolean
  tokens: TokenChip[]
  onCommit: (v: string) => void
}) {
  const { t } = useI18n()
  const { setHelp } = useCharacterFormHost()
  const [local, setLocal] = useState(String(value ?? ''))
  const [resolved, setResolved] = useState('')
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const taRef = useRef<HTMLTextAreaElement>(null)
  useEffect(() => {
    setLocal(String(value ?? ''))
  }, [value])

  // Insert text at the current caret. Reads the LIVE value from the DOM
  // (ta.value) instead of the `local` state — that way a call from the help
  // panel still works after typing (no stale closure).
  const insertText = (ins: string) => {
    const ta = taRef.current
    if (!ta) {
      setLocal((v) => v + ins)
      return
    }
    const cur = ta.value
    const s = ta.selectionStart ?? cur.length
    const e = ta.selectionEnd ?? cur.length
    const next = cur.slice(0, s) + ins + cur.slice(e)
    setLocal(next)
    requestAnimationFrame(() => {
      const el = taRef.current
      if (!el) return
      el.focus()
      const pos = s + ins.length
      el.setSelectionRange(pos, pos)
    })
  }

  // Announce tokens + the insert function to the help panel (on focus). The
  // topic comes from the template's `help` key (e.g. image_prompt for the
  // appearance), otherwise there is no topic.
  const announceHelp = () => setHelp?.(
    typeof field.help === 'string' ? field.help : null,
    {
      items: tokens.map((tk) => ({ code: `{${tk.token}}`, text: tk.label, insert: `{${tk.token}}` })),
      insert: insertText,
    },
  )

  // Debounced resolve through the backend, whenever the text carries tokens.
  useEffect(() => {
    if (timer.current) clearTimeout(timer.current)
    if (!local.includes('{')) {
      setResolved('')
      return
    }
    timer.current = setTimeout(async () => {
      try {
        const r = await apiPost<{ resolved: string }>(
          `/characters/${encodeURIComponent(character)}/resolve-tokens`,
          { text: local, target_key: field.key },
        )
        setResolved(r.resolved && r.resolved !== local ? r.resolved : '')
      } catch {
        setResolved('')
      }
    }, 400)
    return () => {
      if (timer.current) clearTimeout(timer.current)
    }
  }, [local, character, field.key])

  // Its own vertical wrapper: .ga-field-control is a flex ROW, so the textarea
  // and the resolved preview would sit SIDE BY SIDE. This puts the preview
  // directly UNDER the prompt. The insert tokens live in the help panel.
  return (
    <div className="ga-prompt-field">
      <textarea
        ref={taRef}
        className="ga-input"
        rows={Number(field.rows) > 0 ? Number(field.rows) : 12}
        value={local}
        disabled={disabled}
        onFocus={announceHelp}
        onChange={(e) => setLocal(e.target.value)}
        onBlur={() => {
          if (local !== String(value ?? '')) onCommit(local)
        }}
      />
      {resolved ? (
        <div className="tpl-token-preview">
          <span className="tpl-token-preview-label">{t('Preview (resolved)')}</span>
          {resolved}
        </div>
      ) : null}
    </div>
  )
}

export function TemplateTab({
  character,
  tab,
  sections,
  dynamicData,
  specialSlots,
  excludeKeys,
  imageBeside,
  queueField,
  draft,
  discardSignal,
}: {
  character: string
  tab: TmplTabDef
  sections: TmplSectionRaw[]
  dynamicData: DynamicData
  /** A render node per `section.special` (e.g. "placement" → the placement UI). */
  specialSlots?: Record<string, React.ReactNode>
  /** Policy exclusion of single fields (e.g. the social numbers in /play). */
  excludeKeys?: string[]
  /** Render prompt fields that have an image in two columns (prompt left,
   *  image right) instead of the image below — used by the /play avatar panel. */
  imageBeside?: boolean
  /**
   * THE DRAFT, when the container owns one (Game-Admin characters tab).
   *
   * Given `queueField`, a committed field is REMEMBERED instead of POSTed:
   * the container collects everything into one buffer and writes it in one
   * Save per store. Without it this tab behaves exactly as it always did —
   * every blur is its own request — which is what the /play avatar panel
   * still wants, since it has no toolbar to put a Save button in.
   *
   * `opts.reloadAfterSave` forwards the field's `reload_after_save` flag: the
   * container, not this tab, knows when the stores are re-read after its own
   * batch.
   */
  queueField?: (
    scope: 'profile' | 'config',
    key: string,
    value: unknown,
    opts?: { reloadAfterSave?: boolean },
  ) => void
  /** The container's buffered values per store, laid OVER the loaded ones so
   *  a refetch beside the draft cannot eat unsaved work. */
  draft?: { profile?: Record<string, unknown>; config?: Record<string, unknown> }
  /** Bumped by the container's Discard. The fields remount on it, so text
   *  typed but never blurred — it never reached the buffer — falls back to
   *  the server's value too. */
  discardSignal?: number
}) {
  const { t, lang } = useI18n()
  const { toast } = useToast()
  const [profile, setProfile] = useState<Record<string, unknown>>({})
  const [config, setConfig] = useState<Record<string, unknown>>({})
  const [status, setStatus] = useState<Record<string, unknown>>({})
  const [savingKey, setSavingKey] = useState('')
  const [loaded, setLoaded] = useState(false)

  const load = useCallback(async () => {
    if (!character) return
    setLoaded(false)
    try {
      const [pr, cf] = await Promise.all([
        apiGet<{ profile: Record<string, unknown> }>(`/characters/${encodeURIComponent(character)}/profile`),
        apiGet<{ config: Record<string, unknown> }>(`/characters/${encodeURIComponent(character)}/config`),
      ])
      setProfile(pr.profile || {})
      setConfig(cf.config || {})
      const hasStat = sections.some((s) => (s.fields || []).some((f) => f.store === 'status_effects'))
      if (hasStat) {
        try {
          const se = await apiGet<{ status_effects: Record<string, unknown> }>(
            `/characters/${encodeURIComponent(character)}/status-effects`,
          )
          setStatus(se.status_effects || {})
        } catch {
          setStatus({})
        }
      }
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    } finally {
      setLoaded(true)
    }
  }, [character, sections, t, toast])

  useEffect(() => {
    load()
  }, [load])

  // DRAFT OVER SERVER — the one layer every reader below goes through. A
  // field typed away and back must show what is on screen, and `visible_when`
  // must react to the draft too: switching a species in the draft has to
  // reveal that species' fields before the Save, not after it.
  const draftProfile = draft?.profile || {}
  const draftConfig = draft?.config || {}
  const effProfile = draft?.profile ? { ...profile, ...draftProfile } : profile
  const effConfig = draft?.config ? { ...config, ...draftConfig } : config
  // `status_effects` is ONE profile field holding the whole map, so the
  // draft's version of it replaces the loaded one key by key. Memoised
  // because `commit` closes over it: a fresh object per render would rebuild
  // the callback — and with it every field's onCommit — on every keystroke.
  const draftStatus = draftProfile.status_effects as Record<string, unknown> | undefined
  const effStatus = useMemo(
    () => (draftStatus ? { ...status, ...draftStatus } : status),
    [status, draftStatus],
  )

  const lookup = (key: string): unknown =>
    key in effConfig ? effConfig[key] : key in effStatus ? effStatus[key] : effProfile[key]

  const getVal = (f: TmplFieldDef): unknown => {
    const s = asBoolStore(f)
    let v = s === 'config' ? effConfig[f.key] : s === 'status_effects' ? effStatus[f.key] : effProfile[f.key]
    if ((v === '' || v === null || v === undefined) && f.default !== undefined) v = f.default
    return v ?? ''
  }

  const visible = (vw?: { field: string; values: unknown[] }): boolean => {
    if (!vw || !vw.field) return true
    return (vw.values || []).map(String).includes(String(lookup(vw.field) ?? ''))
  }

  const commit = useCallback(
    async (f: TmplFieldDef, raw: string) => {
      const s = asBoolStore(f)
      const value: unknown = f.type === 'number' ? (raw === '' ? '' : Number(raw)) : raw
      // With a container draft the value is only REMEMBERED — same
      // normalisation, same payload shape (`status_effects` as the one merged
      // object it is stored as), just no request and no per-field toast.
      if (queueField) {
        if (s === 'status_effects') {
          queueField('profile', 'status_effects', { ...effStatus, [f.key]: value },
            { reloadAfterSave: !!f.reload_after_save })
        } else {
          queueField(s === 'config' ? 'config' : 'profile', f.key, value,
            { reloadAfterSave: !!f.reload_after_save })
        }
        return
      }
      setSavingKey(f.key)
      try {
        if (s === 'config') {
          await apiPost(`/characters/${encodeURIComponent(character)}/config`, { fields: { [f.key]: value } })
          setConfig((c) => ({ ...c, [f.key]: value }))
        } else if (s === 'status_effects') {
          const merged = { ...status, [f.key]: value }
          await apiPost(`/characters/${encodeURIComponent(character)}/profile`, {
            fields: { status_effects: merged },
          })
          setStatus(merged)
        } else {
          await apiPost(`/characters/${encodeURIComponent(character)}/profile`, { fields: { [f.key]: value } })
          setProfile((p) => ({ ...p, [f.key]: value }))
        }
        toast(t('Saved'))
        // Server-derived siblings (see `reload_after_save`): re-read the
        // stores, because this save wrote keys the form never sent.
        if (f.reload_after_save) load()
      } catch (e) {
        toast(t('Error') + ': ' + (e as Error).message, 'error')
        load()
      } finally {
        setSavingKey('')
      }
    },
    [character, status, effStatus, queueField, t, toast, load],
  )

  const ex = new Set(excludeKeys || [])
  const editableFields = (s: TmplSectionRaw): TmplFieldDef[] =>
    (s.fields || []).filter(
      (f) => f.editor_visible !== false && !f.source_file && !ex.has(f.key) && visible(f.visible_when),
    )

  if (!loaded) return <div className="ga-loading">{t('Loading…')}</div>

  const cols = (tab.columns || []).slice().sort((a, b) => a - b)

  const renderField = (f: TmplFieldDef) => {
    const ro = !!f.readonly || FORCE_READONLY.has(f.key)
    // A Discard has to reach the text a user typed and never blurred: that
    // never became a value, so no prop of the input changes and its own
    // `local` state would keep it on screen. Remounting is what throws it
    // away — the inputs then start from the server's value again.
    const fkey = `${f.key}:${discardSignal ?? 0}`
    const label = (tmplText(f, 'label', lang) || f.key) + (f.required ? ' *' : '')
    const hint = tmplText(f, 'hint', lang)
    const isPrompt = f.type === 'text' && f.multiline
    const imagePreview = typeof f.image_preview === 'string' ? f.image_preview : ''
    const input = isPrompt ? (
      <PromptField
        character={character}
        field={f}
        value={getVal(f)}
        disabled={ro || savingKey === f.key}
        tokens={collectTokens(sections, f.key, lang)}
        onCommit={(v) => commit(f, v)}
      />
    ) : (
      <TemplateField
        field={f}
        value={getVal(f)}
        dynamicData={dynamicData}
        disabled={ro || savingKey === f.key}
        lang={lang}
        onCommit={(v) => commit(f, v)}
      />
    )
    // Side by side (avatar panel): prompt + chips + preview left, image right.
    if (imageBeside && isPrompt && imagePreview) {
      return (
        <div key={fkey} className="tpl-prompt-beside">
          <div className="tpl-prompt-beside-text">
            <Field label={label} hint={hint || undefined} help={typeof f.help === 'string' ? f.help : undefined}>
              {input}
            </Field>
          </div>
          <div className="tpl-prompt-beside-image">
            <FieldImage character={character} kind={imagePreview} />
          </div>
        </div>
      )
    }
    return (
      <div key={fkey}>
        <Field label={label} hint={hint || undefined} help={typeof f.help === 'string' ? f.help : undefined}>
          {input}
        </Field>
        {imagePreview ? <FieldImage character={character} kind={imagePreview} /> : null}
      </div>
    )
  }

  // Columns sit side by side (one per tab.column), with sections stacked
  // in each column and fields stacked in each section. Prompt fields stack
  // prompt → resolved preview → image (see PromptField/renderField).
  return (
    <div className="ga-form tpl-tab-cols">
      {cols.map((col) => {
        const colSections = sections
          .filter((s) => (s.column || 1) === col)
          .filter((s) =>
            s.special ? !!(specialSlots && specialSlots[String(s.special)]) : editableFields(s).length > 0,
          )
          .sort((a, b) => (a.row ?? 0) - (b.row ?? 0))
        return (
          <div key={col} className="tpl-tab-col">
            {colSections.map((s) => (
              <div key={s.id}
                className={`tpl-tab-section${s.grow ? ' tpl-tab-section--grow' : ''}`}>
                <div className="ga-fieldset-title">{tmplText(s, 'label', lang) || s.id}</div>
                {s.special ? specialSlots?.[String(s.special)] : editableFields(s).map(renderField)}
              </div>
            ))}
          </div>
        )
      })}
    </div>
  )
}
