/**
 * PlanOpeningStrip — the selected opening in a room wall: what kind of hole it
 * is, how big, where it leads, and its door or window style.
 *
 * THE THREE SIZES ARE COMMITTED ON BLUR, not on every keystroke: a number
 * field that writes while one types turns "1.2" into a 1 m opening the moment
 * the digit lands, and the plan redraws under the cursor. The `key` on each
 * input carries the stored value, so an outside change (an undo, another
 * strip) still refreshes what the field shows.
 */
import { OpeningWindowStyle } from './WindowStylePicker'
import { useI18n } from '../../i18n/I18nProvider'
import { OpeningDoorProp } from './DoorPropPicker'
import type { Room, RoomOpening } from './worldTypes'

/**
 * ONE metre field of an opening strip, with the blur/`key` discipline the
 * header describes. Exported because the HULL door (PlanHullOpeningStrip) is
 * edited with the same numbers: the two strips differ in what an opening
 * MEANS, never in what one may type into its width.
 */
export function OpeningNumField({ label, value, min, max, title, onCommit }: {
  label: string
  value: number
  min: number
  max: number
  title?: string
  onCommit: (v: number) => void
}) {
  return (
    <label style={{ display: 'inline-flex', gap: 4, alignItems: 'center', fontSize: '0.82em' }}
      title={title}>
      {label}
      <input
        key={`${label}-${value}`}
        className="ga-input"
        type="number"
        min={min}
        max={max}
        step={0.1}
        style={{ width: 64 }}
        defaultValue={value}
        onBlur={(e) => {
          const n = parseFloat(e.target.value)
          if (Number.isFinite(n) && n !== value) {
            onCommit(Math.round(n * 1000) / 1000)
          }
        }}
        onKeyDown={(e) => {
          if (e.key === 'Enter') (e.target as HTMLInputElement).blur()
        }}
      />
    </label>
  )
}

interface Props {
  opening: RoomOpening
  /** Index in the room's `openings`, for the door picker's key — the "Custom,
   *  nothing picked yet" state must never travel to the next opening. */
  index: number
  /** Every OTHER room of the location — where a door may lead. */
  otherRooms: Room[]
  /** The display name of the corridor of THIS room's storey, when that storey
   *  has one (§ A13b). Set = a door without a target leads into it, so the
   *  empty option says so instead of reading like "leads nowhere". */
  corridorName?: string
  /** The location's fallback window style, named as the first option. */
  defaultWindowStyle?: string
  /** The location's fallback door prop, named as the first option. */
  defaultDoorStyle?: string
  defaultDoorPropId: string
  /** Merge a patch into this opening, or remove it when null is passed. */
  onPatch: (patch: Partial<RoomOpening> | null) => void
}

export function PlanOpeningStrip({
  opening: op, index, otherRooms, corridorName = '', defaultDoorPropId, defaultDoorStyle, defaultWindowStyle, onPatch,
}: Props) {
  const { t } = useI18n()

  const numField = (
    field: 'width_m' | 'height_m' | 'sill_m', label: string, max: number,
  ) => (
    <OpeningNumField
      label={label}
      value={op[field]}
      min={field === 'sill_m' ? 0 : 0.4}
      max={max}
      onCommit={(v) => onPatch({ [field]: v })}
    />
  )

  return (
    <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap' }}>
      <span className="ga-hint" style={{ fontWeight: 600 }}>
        🚪 {typeof op.edge === 'string' ? op.edge : `#${op.edge}`} · {op.type}:
      </span>
      <select
        className="ga-input"
        style={{ width: 110 }}
        value={op.type}
        onChange={(e) => onPatch({ type: e.target.value as RoomOpening['type'] })}
        title={t('Door, window or open passage.')}
      >
        <option value="door">{t('Door')}</option>
        <option value="window">{t('Window')}</option>
        <option value="passage">{t('Passage')}</option>
      </select>
      {numField('width_m', t('W (m)'), 10)}
      {numField('height_m', t('H (m)'), 10)}
      {numField('sill_m', t('Sill (m)'), 3)}
      <label style={{ display: 'inline-flex', gap: 4, alignItems: 'center', fontSize: '0.82em' }}
        title={t('Where a door/passage leads — another room, the storey\'s corridor (no target) or outside. Windows leave it empty.')}>
        {t('to')}
        <select
          className="ga-input"
          style={{ width: 130 }}
          value={op.to ?? ''}
          onChange={(e) => onPatch({ to: e.target.value || undefined })}
        >
          <option value="">
            {corridorName ? `→ ${corridorName}` : t('— none —')}
          </option>
          <option value="outside">{t('outside')}</option>
          {otherRooms.map((r) => (
            <option key={r.id} value={r.id}>{r.name || r.id}</option>
          ))}
        </select>
      </label>
      {/* WHICH DOOR hangs in this hole. Only a door has one — a window takes
          no prop and a passage is the open gap by definition
          (`scene_recipe.door_prop_id`). */}
      {op.type === 'door' ? (
        <OpeningDoorProp
          key={index}
          opening={op}
          defaultPropId={defaultDoorPropId}
          defaultStyle={defaultDoorStyle}
          onPatch={onPatch}
        />
      ) : null}
      {op.type === 'window' ? <OpeningWindowStyle opening={op}
        defaultStyle={defaultWindowStyle} onPatch={onPatch} /> : null}
      <button
        type="button"
        className="ga-btn ga-btn-sm ga-btn-danger"
        onClick={() => onPatch(null)}
        title={t('Remove this opening')}
      >
        × {t('Remove')}
      </button>
    </div>
  )
}
