import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useI18n } from '../../i18n/I18nProvider'
import { apiGet, apiPost } from '../../lib/api'
import { useToast } from '../../lib/Toast'
import { ListHeader } from '../../components/ListHeader'
import { ListPane } from '../../components/ListPane'
import { ImportButton } from '../../components/ImportExport'
import { PromptDialog } from '../../components/PromptDialog'
import { loadItems, type ItemRef } from '../../lib/refs'
import { STYLE_HINT_OPTIONS } from '../../lib/styleHints'
import { DANGER_LEVELS, GROUND_ROOM_ID, floorRoomLevel, isFloorRoom, roomLabel, type Location, type Selection } from './worldTypes'
import { LocationEditor } from './LocationEditor'
import { RoomEditor } from './RoomEditor'
import { LocationGallery } from './LocationGallery'

export function WorldTab() {
  const { t } = useI18n()
  const { toast } = useToast()
  const [locations, setLocations] = useState<Location[] | null>(null)
  const [selection, setSelection] = useState<Selection>(null)
  // Unsaved-changes guard: the open LocationEditor reports its dirty state;
  // switching the tree selection then needs a SECOND click (armed pattern —
  // no browser dialogs in this UI) before the draft is discarded.
  const editorDirtyRef = useRef(false)
  const [armedNav, setArmedNav] = useState('')
  const guardedSelect = useCallback((s: Selection) => {
    const key = JSON.stringify(s)
    if (editorDirtyRef.current && JSON.stringify(selection) !== key
        && armedNav !== key) {
      setArmedNav(key)
      toast(t('Unsaved changes — click again to discard them.'), 'error')
      return
    }
    setArmedNav('')
    setSelection(s)
  }, [selection, armedNav, toast, t])
  const [items, setItems] = useState<ItemRef[]>([])

  const reload = useCallback(async () => {
    try {
      const data = await apiGet<{ locations?: Location[] }>('/world/locations')
      // Dedupe by lowercased name as a final guard against legacy data
      // with duplicate labels.
      const seen = new Map<string, Location>()
      for (const loc of data.locations || []) {
        const key = (loc.name || loc.id || '').toLowerCase().trim()
        if (!key) continue
        if (!seen.has(key)) seen.set(key, loc)
      }
      setLocations(Array.from(seen.values()))
    } catch (e) {
      toast(t('Failed to load') + ': ' + (e as Error).message, 'error')
    }
  }, [t, toast])

  useEffect(() => {
    reload()
    loadItems().then(setItems).catch(() => setItems([]))
  }, [reload])

  // One-shot deep link from the Map tab: it stores the location it wants
  // opened and jumps to #/world. Read ONCE on mount and dropped immediately —
  // a later visit must not re-apply a stale selection. Nothing can be dirty
  // at mount time, so this bypasses the unsaved-changes guard by design.
  useEffect(() => {
    let raw: string | null = null
    try {
      raw = sessionStorage.getItem('ga:world:select')
      if (raw) sessionStorage.removeItem('ga:world:select')
    } catch { return }  // storage disabled — no deep link, no harm
    if (!raw) return
    try {
      const want = JSON.parse(raw) as { kind?: string; locationId?: string }
      if (want?.kind === 'location' && want.locationId) {
        setSelection({ kind: 'location', locationId: want.locationId })
      }
    } catch { /* malformed key — ignore */ }
  }, [])

  // Both name questions are in-app dialogs (PromptDialog): the toolbar button
  // only opens the dialog, its submit — which never hands over an empty or
  // untrimmed value — creates. `copyName` is the prefill of the copy dialog.
  const [askNewName, setAskNewName] = useState(false)
  const [copyName, setCopyName] = useState('')
  const newLocation = useCallback(() => { setAskNewName(true) }, [])
  const createLocation = useCallback(async (name: string) => {
    setAskNewName(false)
    try {
      await apiPost('/world/locations', { name, description: '', rooms: [] })
      toast(t('Location created'))
      await reload()
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    }
  }, [reload, t, toast])

  const copyLocation = useCallback(() => {
    if (!locations || !selection || selection.kind !== 'location') return
    const src = locations.find((l) => l.id === selection.locationId)
    if (!src) return
    setCopyName(`${src.name} (copy)`)
  }, [locations, selection])
  const doCopyLocation = useCallback(async (newName: string) => {
    setCopyName('')
    if (!locations || !selection || selection.kind !== 'location') return
    const src = locations.find((l) => l.id === selection.locationId)
    if (!src) return
    try {
      await apiPost('/world/locations', {
        name: newName,
        description: src.description || '',
        // Drop each room's id so the backend assigns FRESH ones — otherwise the
        // copy keeps the source's room IDs and everything keyed by room id
        // (gallery image_rooms, room items, image gen with room_id) collides.
        rooms: (src.rooms || []).map((r) => { const rest = { ...r }; delete rest.id; return rest }),
        image_prompt_day: src.image_prompt_day || '',
        image_prompt_night: src.image_prompt_night || '',
        image_prompt_building: src.image_prompt_building || '',
        danger_level: src.danger_level,
        indoor: src.indoor || '',
        decency: src.decency,
        style_hint: src.style_hint,
        swim_allowed: src.swim_allowed,
        activity_hint: src.activity_hint,
        knowledge_item_id: src.knowledge_item_id,
        // The floor-plan world travels with the copy: map3d carries the
        // SCALE ANCHOR (plan_width_m) the room layouts need — without it the
        // server rightly refuses geometry (user finding 2026-08-03). NOT
        // copied: entry_room — it references a room ID, and the copy gets
        // fresh ones, so it would dangle; pick it anew on the copy.
        map3d: src.map3d,
        terrain: src.terrain,
        event_settings: src.event_settings,
      })
      toast(t('Location copied'))
      await reload()
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    }
  }, [locations, selection, reload, t, toast])

  const selectedLocation = useMemo(() => {
    if (!locations || !selection) return null
    return locations.find((l) => l.id === selection.locationId) || null
  }, [locations, selection])

  const selectedRoom = useMemo(() => {
    if (!selectedLocation || selection?.kind !== 'room') return null
    return (selectedLocation.rooms || []).find((r) => r.id === selection.roomId) || null
  }, [selectedLocation, selection])

  if (locations === null) return <div className="ga-loading">{t('Loading…')}</div>

  return (
    <div className="ga-world-grid">
      {/* Datalist for style-hint suggestions (step 7, May 2026) */}
      <datalist id="style-hint-options">
        {STYLE_HINT_OPTIONS.map((v) => (
          <option key={v} value={v} />
        ))}
      </datalist>
      <ListPane id="locations" className="ga-world-list-col" label={t('Places')}>
        <ListHeader
          title={t('Places')}
          onNew={newLocation}
          onCopy={copyLocation}
          copyDisabled={selection?.kind !== 'location'}
          extra={
            <ImportButton
              onImported={() => reload()}
            />
          }
        />
        <ul className="ga-list">
          {locations.length === 0 ? (
            <li className="ga-list-empty">{t('No places yet')}</li>
          ) : locations.map((l) => (
            <LocationTreeRow key={l.id} location={l} selection={selection} onSelect={guardedSelect} />
          ))}
        </ul>
      </ListPane>
      {selection?.kind === 'location' && selectedLocation ? (
        /* Location view: the tabbed editor (General / 2D / 3D) owns the
           gallery inside its tabs, so it spans the form + gallery columns. */
        <section className="ga-world-form-col ga-world-form-col--wide">
          <LocationEditor
            location={selectedLocation}
            items={items}
            allLocations={locations}
            onChanged={reload}
            onDirty={(d) => {
              editorDirtyRef.current = d
              if (!d) setArmedNav('')
            }}
            onDeleted={() => {
              setSelection(null)
              reload()
            }}
          />
        </section>
      ) : (
        <>
          <section className="ga-world-form-col">
            {selection?.kind === 'room' && selectedLocation && selectedRoom ? (
              <RoomEditor
                location={selectedLocation}
                room={selectedRoom}
                items={items}
                onChanged={reload}
                onDeleted={() => {
                  setSelection({ kind: 'location', locationId: selectedLocation.id })
                  reload()
                }}
              />
            ) : (
              <div className="ga-placeholder">{t('Select a place or room.')}</div>
            )}
          </section>
          <aside className="ga-world-gallery-col">
            {selectedLocation && selectedRoom ? (
              <LocationGallery
                mode="2d"
                locationId={selectedLocation.id}
                location={selectedLocation}
                room={selectedRoom}
                roomFilter={selectedRoom.id || undefined}
                allLocations={locations}
              />
            ) : (
              <div className="ga-placeholder">{t('Select a place to view its gallery.')}</div>
            )}
          </aside>
        </>
      )}

      <PromptDialog
        open={askNewName}
        title={t('New place')}
        label={t('Name of the new location')}
        confirmLabel={t('Create')}
        onSubmit={(name) => { void createLocation(name) }}
        onClose={() => setAskNewName(false)}
      />
      <PromptDialog
        open={!!copyName}
        title={t('Copy place')}
        label={t('Name of the copy')}
        initialValue={copyName}
        confirmLabel={t('Copy')}
        onSubmit={(name) => { void doCopyLocation(name) }}
        onClose={() => setCopyName('')}
      />
    </div>
  )
}

interface LocationTreeRowProps {
  location: Location
  selection: Selection
  onSelect: (s: Selection) => void
}

// Entry-room id of a location: the explicit entry_room when it matches a room,
// otherwise none — analogous to get_entry_room_id (backend). The field is
// optional; without it one arrives on the ground, so there is no implicit
// "first room" entry any more.
function entryRoomId(loc: Location): string {
  const explicit = (loc.entry_room || '').trim()
  if (explicit && (loc.rooms || []).some((r) => r.id === explicit)) return explicit
  return ''
}

// Danger-level color (0 = no display, 1..5 increasingly red).
const DANGER_COLORS = ['', '#6cc24a', '#d9c200', '#e0930b', '#e0560b', '#d62828']

function LocationTreeRow({ location, selection, onSelect }: LocationTreeRowProps) {
  const { t } = useI18n()
  const isLocSelected = selection?.kind === 'location' && selection.locationId === location.id
  const isExpanded = isLocSelected || selection?.locationId === location.id

  // Indoor/outdoor symbol.
  const io = location.indoor === 'indoor'
    ? { icon: '🏠', title: t('Indoor') }
    : location.indoor === 'outdoor'
      ? { icon: '🌳', title: t('Outdoor') }
      : { icon: '', title: '' }
  // Danger-level column.
  const danger = Math.max(0, Math.min(5, location.danger_level || 0))
  const dangerLabel = DANGER_LEVELS.find((d) => d.value === danger)?.label || ''
  // Sort the entry room to the top of the list.
  const eid = entryRoomId(location)
  // Sort: the GROUND always first (user 2026-08-25 — it is the location's own
  // frame, not one room among rooms), then the storey corridors (§ A13b, the
  // same kind of reserved room, ascending by storey), then the entry room,
  // then the rest in their stored order.
  const rank = (r: { id?: string }) =>
    r.id === GROUND_ROOM_ID ? -2 : isFloorRoom(r.id) ? -1.5 : r.id === eid ? -1 : 0
  const rooms = [...(location.rooms || [])].sort((a, b) => rank(a) - rank(b)
    || (floorRoomLevel(a.id) ?? 0) - (floorRoomLevel(b.id) ?? 0))

  return (
    <li>
      <button
        type="button"
        className={`ga-list-row${isLocSelected ? ' is-active' : ''}`}
        onClick={() => onSelect({ kind: 'location', locationId: location.id })}
        title={t('Location')}
      >
        <span className="ga-list-row-main" style={{ display: 'flex', alignItems: 'center', gap: 6, minWidth: 0 }}>
          <span style={{ width: '1.2em', flex: '0 0 auto', textAlign: 'center' }}
            title={io.title || undefined} aria-label={io.title || undefined}>{io.icon}</span>
          <strong style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
            {location.name}
          </strong>
        </span>
        <span style={{ display: 'flex', alignItems: 'center', gap: 8, flex: '0 0 auto', marginLeft: 8 }}>
          {danger > 0 ? (
            <span title={`${t('Danger')}: ${t(dangerLabel)}`}
              style={{ fontSize: '0.72em', fontWeight: 700, color: '#fff', background: DANGER_COLORS[danger],
                borderRadius: 4, padding: '0 5px', lineHeight: 1.6 }}>
              ⚠{danger}
            </span>
          ) : null}
          <span className="ga-form-hint">
            {(location.rooms || []).length} {(location.rooms || []).length === 1 ? 'room' : 'rooms'}
          </span>
        </span>
      </button>
      {isExpanded && rooms.length > 0 ? (
        <ul className="ga-list-nested">
          {rooms.map((r) => {
            const isRoomSelected =
              selection?.kind === 'room' && selection.locationId === location.id && selection.roomId === r.id
            const isEntry = !!r.id && r.id === eid
            // The two reserved rooms may stay unnamed — show the ONE shared
            // default instead of the reserved id (`roomLabel`, so the tree and
            // the floor plan never name one room twice).
            const isGround = r.id === GROUND_ROOM_ID
            const isFloor = isFloorRoom(r.id)
            const label = roomLabel(r, t)
            return (
              <li key={r.id}>
                <button
                  type="button"
                  className={`ga-list-row ga-list-row-nested${isRoomSelected ? ' is-active' : ''}`}
                  onClick={() => onSelect({ kind: 'room', locationId: location.id, roomId: r.id || '' })}
                  title={isEntry ? t('Entry room')
                    : isGround ? t('The ground of this location — the area no room takes up')
                      : isFloor ? t('The corridor of this storey — the area no room of it takes up')
                        : undefined}
                >
                  <span className="ga-list-row-main">
                    {isEntry ? '🚪' : isGround ? '🌐' : isFloor ? '🚶' : '↳'} {label}
                  </span>
                  {r.decency ? <span className="ga-source ga-source-world">{r.decency}</span> : null}
                </button>
              </li>
            )
          })}
        </ul>
      ) : null}
    </li>
  )
}
