/**
 * MindPanel — the avatar’s inner life, replacing JournalPanel.
 * v1: Today, Diary and Memories; navigation also supports future
 * relationship and history sections.
 *
 * Read-only sources:
 *   Today    GET /characters/{character}/memory/today + GET /diary/me/{character}
 *   Diary    GET /diary/me/{character}?date&type&limit&offset, /dates
 *   Memories GET /characters/{character}/memory/list?q&tier&source&related&sort
 * Writes: admin DELETE /diary/me/{character}/entries/{entry_id}; POST /diary/me/{character}/summary (async, then poll).
 * The server ignores the diary routes’ user_id segment, so use "me".
 */
import { Fragment, useEffect, useMemo, useRef, useState } from 'react'
import { useI18n } from './I18nProvider'
import { apiDelete, apiGet, apiPost } from './api'
import { usePoll } from './usePolling'
import { SYNC_ENDPOINTS } from './syncEndpoints'
import { formatDate, formatDateTime, formatTime, sameZoneDay } from './clockFormat'
import { clockSettings, useClockSettings } from './clockSettings'
import { useToast } from './Toast'
import { EmptyState } from './EmptyState'
import { MindThoughtsSection } from './MindThoughtsSection'

// ---------------------------------------------------------------------------
// API shapes
// ---------------------------------------------------------------------------
interface DiaryEntry {
  id?: string
  deletable?: boolean
  type: string
  content: string
  timestamp: string
  end_timestamp?: string
  repeat_count?: number
  metadata?: Record<string, unknown>
}
interface DiaryResponse {
  entries: DiaryEntry[]; types: Record<string, string>; icons: Record<string, string>
  date?: string; date_label?: string
}
/** One selectable game day: the key the API filters by + its world label. */
interface DiaryDate { date: string; date_label: string }

interface TodayStatus {
  location: string; location_id?: string; room?: string; room_id?: string
  activity: string; mood: string
  since?: { activity?: string | null; location?: string | null; mood?: string | null }
  // The server returns an object or null; do not render it as a string (React #31).
  last_warning?: { type: string; value: string; ts?: string } | null
}
interface ActiveMemory {
  id: number; memory_type: string; ts: string; content: string
  importance: number; related_character: string; score: number; tags: string[]
}
interface LanePoint { ts: string; value: string; count?: number }
interface Lane { bucketed: boolean; points: LanePoint[] }
interface Lanes24h { activity: Lane; location: Lane; mood: Lane; effects: Lane }
interface StatItem { key: string; label: string; value: number }
interface TodayResponse {
  character: string; now: string; status: TodayStatus
  stats?: StatItem[]
  lanes_24h?: Lanes24h; active_memories: ActiveMemory[]
}

interface MemoryItem {
  id: number; timestamp: string; memory_type: string; content: string
  tags: string[]; importance: number; access_count: number
  related_character: string; source: string
}
interface MemoryFacets {
  tiers: Record<string, number>
  sources: Record<string, number>
  related_characters: Array<{ name: string; count: number }>
}
interface MemoryListResponse {
  character: string; total: number; total_unfiltered: number
  limit: number; offset: number; items: MemoryItem[]; facets: MemoryFacets
}

interface BondEvent { timestamp: string; type: string; initiator: string; summary: string; sentiment_delta: number }
interface BondItem {
  partner: string; type: string; strength: number
  sentiment_self_to_other: number; sentiment_other_to_self: number
  romantic_tension: number; interaction_count: number
  // "Last met" in WORLD time: the canonical game stamp plus the label the
  // server renders for it — the client never formats a game stamp itself.
  last_interaction_game: string; last_interaction_label: string
  memories_count: number; history_recent: BondEvent[]
}

interface ScheduleSlot {
  hour: number; location: string; location_name: string; role: string; sleep: boolean
}
interface ScheduleResponse { avatar: string; enabled: boolean; slots: ScheduleSlot[] }

type HistoryKind = 'daily' | 'weekly' | 'monthly' | 'history' | 'evolution'
// The keys are world-calendar keys (Y0002-D109 / -W016 / -S01); `label` is the
// readable world date the server renders for them — the client never formats
// a calendar itself.
interface HistoryDailyItem { date: string; label?: string; partner: string; content: string }
interface HistoryPeriodItem { week?: string; month?: string; label?: string; content: string }
type HistoryItem = HistoryDailyItem | HistoryPeriodItem | EvolutionItem
interface HistoryResponse { total?: number; content?: string; items?: HistoryItem[] }
interface EvolutionItem {
  ts: string; trigger: string; beliefs: string; lessons: string; goals: string
  diff: null | Record<'beliefs' | 'lessons' | 'goals', { removed: string[]; added: string[] }>
}

// ---------------------------------------------------------------------------
// Format helpers
//
// These are SYSTEM stamps, so they follow the configured world timezone and
// clock format rather than the viewer's browser locale — read synchronously
// here, subscribed to in the panel component below.
// ---------------------------------------------------------------------------
function clockOf(ts: string): string {
  return formatTime(ts, clockSettings())
}
function dayOf(ts: string): string {
  return formatDate(ts, clockSettings())
}
/** "since" stamp: time only when it happened today, otherwise date + time. */
function sinceOf(ts: string | null | undefined): string {
  if (!ts) return ''
  return sameZoneDay(ts, new Date(), clockSettings()) ? clockOf(ts) : stampOf(ts)
}
/** Full stamp (always date + time) — list entries span multiple days; a
 *  mixed "today = time-only" format makes the list look unsorted. */
function stampOf(ts: string | null | undefined): string {
  if (!ts) return ''
  return formatDateTime(ts, clockSettings())
}
function stars(n: number): string {
  return '★'.repeat(Math.max(0, Math.min(5, Math.round(n))))
}
/** Signed sentiment value with traffic-light colouring. */
function SignedNum({ v }: { v: number }) {
  const color = v > 0.02 ? '#3fa45a' : v < -0.02 ? '#e05656' : 'inherit'
  return (
    <span style={{ color, fontVariantNumeric: 'tabular-nums' }}>
      {(v > 0 ? '+' : '') + v.toFixed(2)}
    </span>
  )
}

/** Directed affection as a coloured bar (-1..1 → 0..100%), with a direction
 *  label and number, as in the old UI: easier to read than numbers alone. */
function SentBar({ v, label }: { v: number; label: string }) {
  const pct = Math.round((Math.max(-1, Math.min(1, v)) + 1) * 50)
  const color = v > 0.2 ? '#3fa45a' : v < -0.2 ? '#e05656' : '#eab308'
  return (
    <div title={`${label}: ${v.toFixed(2)}`} style={{ display: 'flex', alignItems: 'center', gap: 7 }}>
      <span style={{ flex: '1 1 0', minWidth: 0, fontSize: '0.74em', opacity: 0.7,
                     overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{label}</span>
      <div style={{ flex: '0 0 86px', height: 7, borderRadius: 4,
                    background: 'rgba(255,255,255,0.12)', overflow: 'hidden' }}>
        <div style={{ width: `${pct}%`, height: '100%', background: color }} />
      </div>
      <span style={{ flex: '0 0 auto', width: 36, textAlign: 'right', fontSize: '0.72em',
                     opacity: 0.65, fontVariantNumeric: 'tabular-nums' }}>
        {(v > 0 ? '+' : '') + v.toFixed(2)}
      </span>
    </div>
  )
}

// Compact overrides for ga-input, whose solid dark background also keeps
// native option lists from opening in white.
const inputStyle: React.CSSProperties = {
  padding: '3px 8px', fontSize: '0.82em', minWidth: 0,
}
const chipBtnStyle: React.CSSProperties = {
  fontSize: '0.82em', cursor: 'pointer',
}
const sepStyle: React.CSSProperties = {
  margin: '6px 0 2px', fontSize: '0.74em', opacity: 0.55, letterSpacing: 0.4,
  borderBottom: '1px solid rgba(255,255,255,0.12)', paddingBottom: 2,
}

// ---------------------------------------------------------------------------
// Timeline row (Diary/Today): time | icon | content and metadata.
// ---------------------------------------------------------------------------
function TimelineRow({ e, icons, onDelete }: {
  e: DiaryEntry; icons: Record<string, string>; onDelete?: (id: string) => Promise<void>
}) {
  const { t } = useI18n()
  const [confirming, setConfirming] = useState(false)
  const [deleting, setDeleting] = useState(false)
  useEffect(() => {
    if (!confirming) return
    const timer = setTimeout(() => setConfirming(false), 4000)
    return () => clearTimeout(timer)
  }, [confirming])
  const deleteEntry = async () => {
    if (!confirming) { setConfirming(true); return }
    if (!e.id || !onDelete || deleting) return
    setDeleting(true)
    try { await onDelete(e.id) }
    finally { setDeleting(false); setConfirming(false) }
  }
  const meta = e.metadata || {}
  const bits: string[] = []
  if (meta.partner) bits.push(String(meta.partner))
  if (meta.location_name) bits.push(String(meta.location_name))
  if (meta.outcome) bits.push(String(meta.outcome))
  if (e.repeat_count && e.repeat_count > 1) bits.push(`×${e.repeat_count}`)
  return (
    <div style={{ display: 'flex', gap: 8, alignItems: 'baseline' }}>
      <span style={{ flex: '0 0 38px', opacity: 0.5, fontSize: '0.74em', fontVariantNumeric: 'tabular-nums' }}>
        {clockOf(e.timestamp)}
      </span>
      <span style={{ flex: '0 0 auto' }}>{icons[e.type] || '•'}</span>
      <span style={{ flex: 1, minWidth: 0, lineHeight: 1.35 }}>
        {e.content}
        {bits.length > 0 && (
          <span style={{ opacity: 0.5, fontSize: '0.78em' }}> · {bits.join(' · ')}</span>
        )}
      </span>
      {e.deletable && e.id && onDelete && (
        <button className="player-chip" style={chipBtnStyle} disabled={deleting} onClick={deleteEntry}>
          {confirming ? t('Confirm delete') : t('Delete')}
        </button>
      )}
    </div>
  )
}

/** Render entries newest first, separated by day. */
function Timeline({ entries, icons, withDays, onDelete }: {
  entries: DiaryEntry[]; icons: Record<string, string>; withDays: boolean
  onDelete?: (id: string) => Promise<void>
}) {
  const out: React.ReactNode[] = []
  let lastDay = ''
  entries.forEach((e, i) => {
    const day = dayOf(e.timestamp)
    if (withDays && day && day !== lastDay) {
      lastDay = day
      out.push(<div key={`d${day}${i}`} style={sepStyle}>{day}</div>)
    }
    out.push(<TimelineRow key={e.id || `e${i}`} e={e} icons={icons} onDelete={onDelete} />)
  })
  return <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>{out}</div>
}

// ---------------------------------------------------------------------------
// 24-hour lanes: activity, location, mood and effect history as bands.
// ---------------------------------------------------------------------------
/** Stable colour per state value (hash → HSL). Empty means neutral grey. */
function laneColor(value: string): string {
  if (!value) return 'rgba(255,255,255,0.06)'
  let h = 0
  for (let i = 0; i < value.length; i++) h = (h * 31 + value.charCodeAt(i)) % 360
  return `hsl(${h} 42% 44%)`
}

function LaneBand({ icon, label, lane, startMs, endMs }: {
  icon: string; label: string; lane?: Lane; startMs: number; endMs: number
}) {
  const span = Math.max(1, endMs - startMs)
  const pts = lane?.points || []
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
      <span style={{ flex: '0 0 16px', textAlign: 'center' }} title={label}>{icon}</span>
      <div style={{ flex: 1, position: 'relative', height: 13, borderRadius: 4,
                    background: 'rgba(255,255,255,0.05)', overflow: 'hidden' }}>
        {pts.map((p, i) => {
          const t0 = Date.parse(p.ts)
          if (isNaN(t0)) return null
          const tNext = i + 1 < pts.length ? Date.parse(pts[i + 1].ts) : endMs
          const segStart = Math.max(startMs, t0)
          const segEnd = Math.min(endMs, isNaN(tNext) ? endMs : tNext)
          if (segEnd <= segStart) return null
          const left = ((segStart - startMs) / span) * 100
          const width = ((segEnd - segStart) / span) * 100
          return (
            <div key={i}
              title={`${p.value || '—'} · ${clockOf(p.ts)}${p.count ? ` ×${p.count}` : ''}`}
              style={{ position: 'absolute', top: 0, bottom: 0, left: `${left}%`,
                       width: `${Math.max(0.7, width)}%`, background: laneColor(p.value) }} />
          )
        })}
      </div>
    </div>
  )
}

function Lanes24h({ lanes, nowIso }: { lanes?: Lanes24h; nowIso: string }) {
  const { t } = useI18n()
  if (!lanes) return null
  const hasData = (['activity', 'location', 'mood', 'effects'] as const)
    .some((k) => (lanes[k]?.points || []).length > 0)
  if (!hasData) return null
  const endMs = Date.parse(nowIso) || Date.now()
  const startMs = endMs - 24 * 3600 * 1000
  return (
    <div>
      <div style={sepStyle}>{t('Last 24h')}</div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
        <LaneBand icon="🎭" label={t('Activity')} lane={lanes.activity} startMs={startMs} endMs={endMs} />
        <LaneBand icon="📍" label={t('Location')} lane={lanes.location} startMs={startMs} endMs={endMs} />
        <LaneBand icon="🙂" label={t('Mood')} lane={lanes.mood} startMs={startMs} endMs={endMs} />
        <LaneBand icon="✨" label={t('Effects')} lane={lanes.effects} startMs={startMs} endMs={endMs} />
        <div style={{ display: 'flex', justifyContent: 'space-between', paddingLeft: 22,
                      fontSize: '0.66em', opacity: 0.4, fontVariantNumeric: 'tabular-nums' }}>
          <span>{clockOf(new Date(startMs).toISOString())}</span>
          <span>{t('now')}</span>
        </div>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Today: status, 24-hour lanes, active memories and timeline.
// ---------------------------------------------------------------------------
function TodayView({ character, onOpenMemories }: { character: string; onOpenMemories?: () => void }) {
  const { t } = useI18n()
  const [today, setToday] = useState<TodayResponse | null>(null)
  const [diary, setDiary] = useState<DiaryResponse | null>(null)
  const enc = encodeURIComponent(character)

  // Steady 10s poll (today status + diary) via the shared hub.
  const { data: td } = usePoll<{ today: TodayResponse; diary: DiaryResponse }>(
    `mind-today:${enc}`,
    async () => {
      const [today, diary] = await Promise.all([
        apiGet<TodayResponse>(`/characters/${enc}/memory/today`),
        apiGet<DiaryResponse>(`/diary/me/${enc}?limit=200`),
      ])
      return { today, diary }
    },
    SYNC_ENDPOINTS.mind)
  useEffect(() => {
    if (td) { setToday(td.today); setDiary(td.diary) }
  }, [td])

  if (!today) return <EmptyState small icon="journal" title={t('Loading…')} />
  const s = today.status || ({} as TodayStatus)
  const since = s.since || {}

  const statusRow = (icon: string, value: string, sinceTs?: string | null) => value ? (
    <div style={{ display: 'flex', gap: 7, alignItems: 'baseline', minWidth: 0 }}>
      <span style={{ flex: '0 0 auto' }}>{icon}</span>
      <span style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{value}</span>
      {sinceTs ? (
        <span style={{ flex: '0 0 auto', opacity: 0.45, fontSize: '0.74em' }}>
          {t('since')} {sinceOf(sinceTs)}
        </span>
      ) : null}
    </div>
  ) : null

  const stats = today.stats || []

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
      <div style={{ display: 'flex', gap: 16, padding: '6px 8px',
                    borderRadius: 8, background: 'rgba(255,255,255,0.05)' }}>
        <div style={{ flex: '0 1 auto', minWidth: 0, display: 'flex', flexDirection: 'column', gap: 4 }}>
          {statusRow('📍', [s.location, s.room].filter(Boolean).join(' · '), since.location)}
          {statusRow('🎭', s.activity, since.activity)}
          {statusRow('🙂', s.mood, since.mood)}
          {s.last_warning ? (
            <div style={{ fontSize: '0.78em', color: '#e0a356' }}>
              ⚠ {s.last_warning.type === 'access_denied' ? t('Blocked') : t('Forced action')}: {s.last_warning.value}
            </div>
          ) : null}
        </div>
        {stats.length > 0 ? (
          <div style={{ flex: '0 0 auto', display: 'grid', alignContent: 'start',
                        gridTemplateColumns: 'auto auto', columnGap: 8, rowGap: 2,
                        fontSize: '0.78em', borderLeft: '1px solid rgba(255,255,255,0.12)',
                        paddingLeft: 10 }}>
            {stats.map((st) => (
              <Fragment key={st.key}>
                <span style={{ opacity: 0.6, whiteSpace: 'nowrap' }}>{st.label}</span>
                <span style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{st.value}</span>
              </Fragment>
            ))}
          </div>
        ) : null}
      </div>

      <Lanes24h lanes={today.lanes_24h} nowIso={today.now} />

      {/* Active memories beside status: both describe the current state.
          Show the top six, with the full archive one click away, leaving
          the expanding lower area for the daily timeline. */}
      {today.active_memories && today.active_memories.length > 0 && (
        <div>
          <div style={{ ...sepStyle, display: 'flex', alignItems: 'baseline' }}
               title={t('What is on their mind right now — top memories ranked by importance, decay and recency. The Memories section is the full searchable archive.')}>
            <span>{t('Active memories')}</span>
            {onOpenMemories && (
              <button onClick={onOpenMemories}
                style={{ marginLeft: 'auto', background: 'none', border: 0, padding: 0,
                         cursor: 'pointer', color: 'var(--accent, #6aa9ff)', fontSize: '1em' }}>
                {t('all')} →
              </button>
            )}
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 5 }}>
            {today.active_memories.slice(0, 6).map((m) => (
              <div key={m.id} style={{ display: 'flex', flexDirection: 'column', gap: 1,
                                       padding: '3px 6px', borderRadius: 6, background: 'rgba(255,255,255,0.04)' }}>
                <div style={{ lineHeight: 1.3 }}>{m.content}</div>
                <div style={{ display: 'flex', gap: 8, fontSize: '0.72em', opacity: 0.55, flexWrap: 'wrap' }}>
                  <span>{stars(m.importance)}</span>
                  <span>{m.memory_type}</span>
                  {m.related_character ? <span>· {m.related_character}</span> : null}
                  <span style={{ marginLeft: 'auto' }}>{sinceOf(m.ts)}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div>
        <div style={sepStyle}>{t('Today')}</div>
        {diary && diary.entries.length > 0
          ? <Timeline entries={diary.entries} icons={diary.icons || {}} withDays={false} />
          : <EmptyState small icon="journal" title={t('No entries yet')} />}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Diary: date/type filters, search, timeline and daily summary.
// ---------------------------------------------------------------------------
function DiaryView({ character, canDeleteEntries }: { character: string; canDeleteEntries: boolean }) {
  const { toast } = useToast()
  const { t, lang } = useI18n()
  const enc = encodeURIComponent(character)
  const LIMIT = 100
  // Game days: `date` is the world-day key the server filters by, `date_label`
  // its readable world date. The client never derives one from the other.
  const [dates, setDates] = useState<DiaryDate[]>([])
  const [date, setDate] = useState<string>('')        // '' = today (server default)
  const [typeFilter, setTypeFilter] = useState<string>('')
  const [q, setQ] = useState('')
  const [data, setData] = useState<DiaryResponse | null>(null)
  const [entries, setEntries] = useState<DiaryEntry[]>([])
  const [offset, setOffset] = useState(0)
  const [mayHaveMore, setMayHaveMore] = useState(false)
  const [genState, setGenState] = useState<'' | 'generating' | 'done' | 'exists' | 'empty' | 'error'>('')

  useEffect(() => {
    apiGet<DiaryDate[]>(`/diary/me/${enc}/dates?lang=${encodeURIComponent(lang)}`)
      .then(setDates).catch(() => setDates([]))
  }, [enc, lang])

  const load = async (newOffset: number, append: boolean) => {
    const params = new URLSearchParams()
    if (date) params.set('date', date)
    if (typeFilter) params.set('type', typeFilter)
    params.set('limit', String(LIMIT))
    params.set('offset', String(newOffset))
    try {
      const d = await apiGet<DiaryResponse>(`/diary/me/${enc}?${params.toString()}`)
      setData(d)
      setEntries((prev) => append ? [...prev, ...d.entries] : d.entries)
      setOffset(newOffset)
      setMayHaveMore(d.entries.length >= LIMIT)
    } catch { /* offline/auth */ }
  }
  useEffect(() => { load(0, false) }, [enc, date, typeFilter]) // eslint-disable-line react-hooks/exhaustive-deps

  // After generating a summary, poll for daily_summary for up to 90 seconds;
  // the endpoint returns before generation finishes.
  useEffect(() => {
    if (genState !== 'generating') return
    let tries = 0
    const id = setInterval(async () => {
      tries += 1
      await load(0, false)
      if (tries >= 22) { setGenState('error'); clearInterval(id) }
    }, 4000)
    return () => clearInterval(id)
  }, [genState]) // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (genState === 'generating' && entries.some((e) => e.type === 'daily_summary')) {
      setGenState('done')
    }
  }, [entries, genState])

  const generateSummary = async () => {
    setGenState('generating')
    try {
      await apiPost(`/diary/me/${enc}/summary`, date ? { date } : {})
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      if (msg.includes('409')) setGenState('exists')
      else if (msg.includes('404')) setGenState('empty')
      else setGenState('error')
    }
  }

  const deleteEntry = async (id: string) => {
    try {
      await apiDelete(`/diary/me/${enc}/entries/${encodeURIComponent(id)}`)
      setEntries((prev) => prev.filter((entry) => entry.id !== id))
      // The next page starts one row earlier after removing a loaded row.
      setOffset((prev) => prev - 1)
    } catch {
      toast(t('Could not delete entry'), 'error')
    }
  }

  const needle = q.trim().toLowerCase()
  const visible = needle
    ? entries.filter((e) => (e.content || '').toLowerCase().includes(needle))
    : entries
  const types = data?.types || {}
  const icons = data?.icons || {}
  const genLabel: Record<string, string> = {
    generating: t('generating…'), done: t('done'),
    exists: t('already summarized'), empty: t('no events for this day'), error: t('failed'),
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 8, height: '100%', minHeight: 0 }}>
      <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', flex: '0 0 auto', alignItems: 'center' }}>
        <select className="ga-input" style={inputStyle} value={date} onChange={(e) => setDate(e.target.value)}>
          <option value="">{t('Today')}</option>
          <option value="all">{t('All days')}</option>
          {dates.map((d) => (
            <option key={d.date} value={d.date}>{d.date_label || d.date}</option>
          ))}
        </select>
        <select className="ga-input" style={inputStyle} value={typeFilter} onChange={(e) => setTypeFilter(e.target.value)}>
          <option value="">{t('All types')}</option>
          {Object.keys(types).map((k) => (
            <option key={k} value={k}>{(icons[k] ? icons[k] + ' ' : '') + (types[k] || k)}</option>
          ))}
        </select>
        <input className="ga-input" style={{ ...inputStyle, flex: 1, minWidth: 70 }} placeholder={t('Search…')}
               value={q} onChange={(e) => setQ(e.target.value)} />
      </div>

      {date !== 'all' && (
        <div style={{ display: 'flex', gap: 8, alignItems: 'center', flex: '0 0 auto' }}>
          <button
            onClick={generateSummary}
            disabled={genState === 'generating'}
            className="player-chip"
            style={{ ...chipBtnStyle, cursor: genState === 'generating' ? 'wait' : 'pointer' }}>
            📔 {t('Generate day summary')}
          </button>
          {genState ? <span style={{ fontSize: '0.76em', opacity: 0.6 }}>{genLabel[genState] || ''}</span> : null}
        </div>
      )}

      <div style={{ flex: 1, minHeight: 0, overflow: 'auto' }}>
        {visible.length === 0
          ? <EmptyState small icon="journal" title={t('No entries')} />
          : <Timeline entries={visible} icons={icons} withDays={date === 'all'}
                      onDelete={canDeleteEntries ? deleteEntry : undefined} />}
        {mayHaveMore && !needle && (
          <button className="player-chip" style={{ ...chipBtnStyle, marginTop: 8 }}
                  onClick={() => load(offset + LIMIT, true)}>
            {t('Load more')}
          </button>
        )}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Memories: faceted search through memory/list.
// ---------------------------------------------------------------------------
function MemoriesView({ character, initialRelated = '' }: { character: string; initialRelated?: string }) {
  const { t } = useI18n()
  const enc = encodeURIComponent(character)
  const LIMIT = 50
  const [q, setQ] = useState('')
  const [qDebounced, setQDebounced] = useState('')
  const [tier, setTier] = useState('')
  const [source, setSource] = useState('')
  const [related, setRelated] = useState(initialRelated)
  const [sort, setSort] = useState('recent')
  const [resp, setResp] = useState<MemoryListResponse | null>(null)
  const [items, setItems] = useState<MemoryItem[]>([])
  const [offset, setOffset] = useState(0)

  useEffect(() => {
    const id = setTimeout(() => setQDebounced(q.trim()), 300)
    return () => clearTimeout(id)
  }, [q])

  const load = async (newOffset: number, append: boolean) => {
    const params = new URLSearchParams()
    params.set('limit', String(LIMIT))
    params.set('offset', String(newOffset))
    params.set('sort', sort)
    if (qDebounced) params.set('q', qDebounced)
    if (tier) params.set('tier', tier)
    if (source) params.set('source', source)
    if (related) params.set('related', related)
    try {
      const d = await apiGet<MemoryListResponse>(`/characters/${enc}/memory/list?${params.toString()}`)
      setResp(d)
      setItems((prev) => append ? [...prev, ...d.items] : d.items)
      setOffset(newOffset)
    } catch { /* offline/auth */ }
  }
  useEffect(() => { load(0, false) }, [enc, qDebounced, tier, source, related, sort]) // eslint-disable-line react-hooks/exhaustive-deps

  const facets = resp?.facets
  const total = resp?.total ?? 0
  const optionList = (rec: Record<string, number> | undefined) =>
    Object.entries(rec || {}).map(([k, n]) => (
      <option key={k} value={k}>{k} ({n})</option>
    ))

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 8, height: '100%', minHeight: 0 }}>
      <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', flex: '0 0 auto' }}>
        <input className="ga-input" style={{ ...inputStyle, flex: '1 1 100%', minWidth: 90 }} placeholder={t('Search…')}
               value={q} onChange={(e) => setQ(e.target.value)} />
        <select className="ga-input" style={inputStyle} value={tier} onChange={(e) => setTier(e.target.value)}>
          <option value="">{t('All tiers')}</option>
          {optionList(facets?.tiers)}
        </select>
        <select className="ga-input" style={inputStyle} value={source} onChange={(e) => setSource(e.target.value)}>
          <option value="">{t('All sources')}</option>
          {optionList(facets?.sources)}
        </select>
        <select className="ga-input" style={inputStyle} value={related} onChange={(e) => setRelated(e.target.value)}>
          <option value="">{t('Anyone')}</option>
          {related && !(facets?.related_characters || []).some((r) => r.name === related) && (
            <option value={related}>{related}</option>
          )}
          {(facets?.related_characters || []).map((r) => (
            <option key={r.name} value={r.name}>{r.name} ({r.count})</option>
          ))}
        </select>
        <select className="ga-input" style={inputStyle} value={sort} onChange={(e) => setSort(e.target.value)}>
          <option value="recent">{t('Recent')}</option>
          <option value="importance">{t('Importance')}</option>
          <option value="access">{t('Most accessed')}</option>
          <option value="score">{t('Score')}</option>
        </select>
      </div>

      <div style={{ fontSize: '0.74em', opacity: 0.5, flex: '0 0 auto' }}>
        {t('{n} memories').replace('{n}', String(total))}
      </div>

      <div style={{ flex: 1, minHeight: 0, overflow: 'auto', display: 'flex', flexDirection: 'column', gap: 5 }}>
        {items.length === 0
          ? <EmptyState small icon="journal" title={t('No memories found')} />
          : items.map((m) => (
            <div key={m.id} style={{ display: 'flex', flexDirection: 'column', gap: 2,
                                     padding: '4px 6px', borderRadius: 6, background: 'rgba(255,255,255,0.04)' }}>
              <div style={{ lineHeight: 1.3 }}>{m.content}</div>
              <div style={{ display: 'flex', gap: 8, fontSize: '0.72em', opacity: 0.55, flexWrap: 'wrap' }}>
                <span>{stars(m.importance)}</span>
                <span>{m.memory_type}</span>
                {m.related_character ? <span>· {m.related_character}</span> : null}
                {m.source ? <span>· {m.source}</span> : null}
                {(m.tags || []).slice(0, 4).map((tag) => (
                  <span key={tag} style={{ border: '1px solid rgba(255,255,255,0.2)', borderRadius: 8,
                                           padding: '0 6px' }}>{tag}</span>
                ))}
                <span style={{ marginLeft: 'auto' }}>{stampOf(m.timestamp)}</span>
              </div>
            </div>
          ))}
        {items.length < total && (
          <button className="player-chip" style={{ ...chipBtnStyle, alignSelf: 'flex-start' }}
                  onClick={() => load(offset + LIMIT, true)}>
            {t('Load more')} ({items.length}/{total})
          </button>
        )}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// "Relationships" section — sentiment/tension/interactions per partner
// ---------------------------------------------------------------------------
function BondsView({ character, onOpenMemories }: {
  character: string; onOpenMemories?: (partner: string) => void
}) {
  const { t, lang } = useI18n()
  const enc = encodeURIComponent(character)
  const [items, setItems] = useState<BondItem[] | null>(null)
  const [open, setOpen] = useState<string>('')   // partner whose history is expanded

  useEffect(() => {
    let alive = true
    const params = new URLSearchParams({ history_limit: '10', lang })
    apiGet<{ items: BondItem[] }>(`/characters/${enc}/memory/relationships?${params.toString()}`)
      .then((d) => { if (alive) setItems(d.items || []) })
      .catch(() => { if (alive) setItems([]) })
    return () => { alive = false }
  }, [enc, lang])

  if (items === null) return <EmptyState small icon="journal" title={t('Loading…')} />
  if (items.length === 0) return <EmptyState small icon="journal" title={t('No relationships')} />

  return (
    <div style={{ height: '100%', minHeight: 0, overflowY: 'auto', overflowX: 'hidden',
                  display: 'grid', gap: 6, alignContent: 'start',
                  gridTemplateColumns: 'repeat(auto-fill, minmax(240px, 1fr))' }}>
      {items.map((b) => {
        const expanded = open === b.partner
        return (
          <div key={b.partner} style={{ minWidth: 0, padding: '5px 7px', borderRadius: 6, background: 'rgba(255,255,255,0.04)' }}>
            <div style={{ display: 'flex', gap: 8, alignItems: 'baseline', cursor: 'pointer' }}
                 onClick={() => setOpen(expanded ? '' : b.partner)}>
              <span style={{ fontWeight: 600, minWidth: 0, overflow: 'hidden',
                             textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{b.partner}</span>
              <span style={{ fontSize: '0.72em', opacity: 0.55, border: '1px solid rgba(255,255,255,0.2)',
                             borderRadius: 8, padding: '0 6px', flex: '0 0 auto' }}>{b.type}</span>
              <span title={t('bond strength')} style={{ fontSize: '0.72em', opacity: 0.6, flex: '0 0 auto' }}>⚡ {b.strength}</span>
              {b.romantic_tension > 0 && (
                <span title={t('romantic tension')} style={{ fontSize: '0.72em', flex: '0 0 auto', color: '#d77bae' }}>
                  ♥ {b.romantic_tension.toFixed(2)}
                </span>
              )}
              <span style={{ marginLeft: 'auto', flex: '0 0 auto', opacity: 0.5, fontSize: '0.8em' }}>{expanded ? '▾' : '▸'}</span>
            </div>
            {/* Directed affection as bars */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: 3, marginTop: 5 }}>
              <SentBar v={b.sentiment_self_to_other} label={`${character} → ${b.partner}`} />
              <SentBar v={b.sentiment_other_to_self} label={`${b.partner} → ${character}`} />
            </div>
            <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'baseline',
                          fontSize: '0.74em', opacity: 0.6, marginTop: 4 }}>
              <span>{t('{n}×').replace('{n}', String(b.interaction_count))}</span>
              {b.last_interaction_label
                ? <span title={t('last met')}>· {b.last_interaction_label}</span> : null}
              {b.memories_count > 0 && onOpenMemories && (
                <button onClick={(ev) => { ev.stopPropagation(); onOpenMemories(b.partner) }}
                  style={{ marginLeft: 'auto', background: 'none', border: 0, padding: 0, cursor: 'pointer',
                           color: 'var(--accent, #6aa9ff)', fontSize: '1em' }}>
                  {t('{n} memories').replace('{n}', String(b.memories_count))} →
                </button>
              )}
            </div>
            {expanded && b.history_recent.length > 0 && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 3, marginTop: 5,
                            paddingTop: 4, borderTop: '1px solid rgba(255,255,255,0.1)' }}>
                {b.history_recent.map((ev, i) => (
                  <div key={i} style={{ display: 'flex', gap: 7, alignItems: 'baseline', fontSize: '0.78em' }}>
                    <span style={{ flex: '0 0 auto', opacity: 0.45, fontVariantNumeric: 'tabular-nums' }}>
                      {sinceOf(ev.timestamp)}
                    </span>
                    <span style={{ flex: 1, minWidth: 0, opacity: 0.85, lineHeight: 1.3 }}>{ev.summary || ev.type}</span>
                    {typeof ev.sentiment_delta === 'number' && ev.sentiment_delta !== 0 && (
                      <span style={{ flex: '0 0 auto' }}><SignedNum v={ev.sentiment_delta} /></span>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}

// ---------------------------------------------------------------------------
// History: daily/weekly/monthly summaries, total and evolution diffs
// ---------------------------------------------------------------------------
function HistoryView({ character }: { character: string }) {
  const { t, lang } = useI18n()
  const enc = encodeURIComponent(character)
  const LIMIT = 30
  const [kind, setKind] = useState<HistoryKind>('daily')
  const [resp, setResp] = useState<HistoryResponse | null>(null)
  const [items, setItems] = useState<HistoryItem[]>([])
  const [offset, setOffset] = useState(0)

  const load = async (newOffset: number, append: boolean) => {
    const params = new URLSearchParams({ kind, limit: String(LIMIT), offset: String(newOffset), lang })
    try {
      const d = await apiGet<HistoryResponse>(`/characters/${enc}/memory/history?${params.toString()}`)
      setResp(d)
      setItems((prev) => append ? [...prev, ...(d.items || [])] : (d.items || []))
      setOffset(newOffset)
    } catch { /* offline/auth */ }
  }
  useEffect(() => { setResp(null); load(0, false) }, [enc, kind]) // eslint-disable-line react-hooks/exhaustive-deps

  const kinds: Array<{ id: HistoryKind; label: string }> = [
    { id: 'daily', label: t('Daily') },
    { id: 'weekly', label: t('Weekly') },
    { id: 'monthly', label: t('Seasons') },
    { id: 'history', label: t('Overall') },
    { id: 'evolution', label: t('Evolution') },
  ]
  const total: number = resp?.total ?? 0
  const paged = kind === 'daily'   // Only daily entries are paginated by the server.

  const evoDiffRows = (label: string, d?: { removed: string[]; added: string[] }) => {
    if (!d || (d.added.length === 0 && d.removed.length === 0)) return null
    return (
      <div key={label} style={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
        <div style={{ fontSize: '0.72em', opacity: 0.5, textTransform: 'uppercase', letterSpacing: 0.4 }}>{label}</div>
        {d.added.map((line, i) => (
          <div key={`a${i}`} style={{ color: '#3fa45a', fontSize: '0.82em', lineHeight: 1.3 }}>+ {line}</div>
        ))}
        {d.removed.map((line, i) => (
          <div key={`r${i}`} style={{ color: '#e05656', fontSize: '0.82em', lineHeight: 1.3,
                                      textDecoration: 'line-through', opacity: 0.75 }}>− {line}</div>
        ))}
      </div>
    )
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 8, height: '100%', minHeight: 0 }}>
      <div style={{ display: 'flex', gap: 5, flexWrap: 'wrap', flex: '0 0 auto' }}>
        {kinds.map((k) => (
          <button key={k.id} className={'player-chip' + (kind === k.id ? ' on' : '')}
                  style={{ ...chipBtnStyle, ...(kind === k.id ? {
                    borderColor: 'var(--accent, #6aa9ff)', background: 'rgba(120,170,255,0.18)',
                  } : {}) }}
                  onClick={() => setKind(k.id)}>
            {k.label}
          </button>
        ))}
      </div>

      <div style={{ flex: 1, minHeight: 0, overflow: 'auto', display: 'flex', flexDirection: 'column', gap: 6 }}>
        {resp === null ? (
          <EmptyState small icon="journal" title={t('Loading…')} />
        ) : kind === 'history' ? (
          (resp.content || '').trim()
            ? <div style={{ whiteSpace: 'pre-wrap', lineHeight: 1.4 }}>{resp.content}</div>
            : <EmptyState small icon="journal" title={t('No summary yet')} />
        ) : items.length === 0 ? (
          <EmptyState small icon="journal" title={t('No entries')} />
        ) : kind === 'evolution' ? (
          (items as EvolutionItem[]).map((s, i) => (
            <div key={i} style={{ padding: '5px 7px', borderRadius: 6, background: 'rgba(255,255,255,0.04)',
                                  display: 'flex', flexDirection: 'column', gap: 4 }}>
              <div style={{ display: 'flex', gap: 8, alignItems: 'baseline' }}>
                <span style={{ fontSize: '0.74em', opacity: 0.5, fontVariantNumeric: 'tabular-nums' }}>{sinceOf(s.ts)}</span>
                {s.trigger ? <span style={{ fontSize: '0.78em', opacity: 0.7 }}>{s.trigger}</span> : null}
              </div>
              {s.diff ? (
                [evoDiffRows(t('Beliefs'), s.diff.beliefs),
                 evoDiffRows(t('Lessons'), s.diff.lessons),
                 evoDiffRows(t('Goals'), s.diff.goals)].filter(Boolean).length > 0
                  ? <>
                      {evoDiffRows(t('Beliefs'), s.diff.beliefs)}
                      {evoDiffRows(t('Lessons'), s.diff.lessons)}
                      {evoDiffRows(t('Goals'), s.diff.goals)}
                    </>
                  : <div style={{ fontSize: '0.78em', opacity: 0.5 }}>{t('no changes')}</div>
              ) : (
                <div style={{ fontSize: '0.82em', opacity: 0.8, lineHeight: 1.35 }}>
                  {[s.beliefs, s.lessons, s.goals].filter(Boolean).join(' · ')}
                </div>
              )}
            </div>
          ))
        ) : (
          <>
            {(items as Array<HistoryDailyItem & HistoryPeriodItem>).map((it, i) => (
              <div key={i} style={{ display: 'flex', flexDirection: 'column', gap: 2,
                                    padding: '4px 6px', borderRadius: 6, background: 'rgba(255,255,255,0.04)' }}>
                <div style={{ display: 'flex', gap: 8, fontSize: '0.74em', opacity: 0.55 }}>
                  <span style={{ fontVariantNumeric: 'tabular-nums' }}
                        title={it.date || it.week || it.month}>
                    {it.label || it.date || it.week || it.month}
                  </span>
                  {it.partner ? <span>· {it.partner}</span> : null}
                </div>
                <div style={{ lineHeight: 1.35 }}>{it.content}</div>
              </div>
            ))}
            {paged && items.length < total && (
              <button className="player-chip" style={{ ...chipBtnStyle, alignSelf: 'flex-start' }}
                      onClick={() => load(offset + LIMIT, true)}>
                {t('Load more')} ({items.length}/{total})
              </button>
            )}
          </>
        )}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Daily schedule: the avatar’s rhythm, read-only (R5).
// ---------------------------------------------------------------------------
/** The avatar's daily schedule as a plain hour → activity list. Read-only:
 *  editing lives in the Game-Admin scheduler, this is what the player sees. */
function ScheduleView({ data }: { data: ScheduleResponse | null }) {
  const { t } = useI18n()
  if (!data) return <EmptyState small icon="journal" title={t('Loading…')} />
  const slots = data.enabled ? (data.slots || []) : []
  if (slots.length === 0) {
    return <EmptyState small icon="journal" title={t('No daily schedule set')} />
  }
  return (
    <div style={{ height: '100%', minHeight: 0, overflow: 'auto',
                  display: 'flex', flexDirection: 'column', gap: 4 }}>
      {slots.map((s) => (
        <div key={s.hour} style={{ display: 'flex', gap: 10, alignItems: 'baseline',
                                   padding: '4px 6px', borderRadius: 6,
                                   background: 'rgba(255,255,255,0.04)' }}>
          <span style={{ flex: '0 0 44px', opacity: 0.55, fontSize: '0.8em',
                         fontVariantNumeric: 'tabular-nums' }}>
            {String(s.hour).padStart(2, '0')}:00
          </span>
          {s.sleep ? (
            <span style={{ opacity: 0.75 }}>💤 {t('Asleep')}</span>
          ) : (
            <span style={{ flex: 1, minWidth: 0, lineHeight: 1.3 }}>
              {s.role || <span style={{ opacity: 0.5 }}>{t('free')}</span>}
              {s.location_name && (
                <span style={{ opacity: 0.55, fontSize: '0.8em' }}> · 📍 {s.location_name}</span>
              )}
            </span>
          )}
        </div>
      ))}
    </div>
  )
}

// ---------------------------------------------------------------------------
// Main panel: navigation left (icons when narrow), section content right.
// ---------------------------------------------------------------------------
type SectionId = 'today' | 'diary' | 'memories' | 'bonds' | 'history' | 'thoughts' | 'schedule'

export function MindPanel({ character, alwaysLabels = false, withThoughts = false, canDeleteEntries = false }: {
  character: string
  alwaysLabels?: boolean
  /** Admin diary controls; the server separately enforces administrator access. */
  canDeleteEntries?: boolean
  /** ADMIN ONLY: adds the private thought-journal section (Game-Admin Mind
   *  tab). Never set from /play — thoughts must not reach a player surface,
   *  and the endpoint behind the section is admin-gated anyway. */
  withThoughts?: boolean
}) {
  // Subscribe to the shared clock settings so the stamp helpers above
  // re-render once the server-configured format and timezone arrive.
  useClockSettings()
  const { t } = useI18n()
  const [section, setSection] = useState<SectionId>('today')
  const [narrowRaw, setNarrowRaw] = useState(false)
  const narrow = narrowRaw && !alwaysLabels
  const rootRef = useRef<HTMLDivElement | null>(null)

  // Below 340px, navigation collapses to icons. Game-admin disables this
  // through alwaysLabels because labels are wanted there.
  useEffect(() => {
    const el = rootRef.current
    if (!el || typeof ResizeObserver === 'undefined') return
    const ro = new ResizeObserver((ents) => {
      const w = ents[0]?.contentRect?.width || 0
      setNarrowRaw(w > 0 && w < 340)
    })
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  // Preselect the related character when navigating from Relationships to Memories.
  const [memRelated, setMemRelated] = useState('')
  const openMemories = (partner = '') => { setMemRelated(partner); setSection('memories') }

  // The daily schedule is served for the AVATAR only (GET /play/schedule
  // resolves it server-side). The section therefore appears exactly when this
  // panel shows the avatar — in the Game-Admin, looking at somebody else, it
  // stays hidden rather than showing the wrong person's rhythm.
  const [schedule, setSchedule] = useState<ScheduleResponse | null>(null)
  useEffect(() => {
    let alive = true
    apiGet<ScheduleResponse>('/play/schedule')
      .then((d) => { if (alive) setSchedule(d) })
      .catch(() => { if (alive) setSchedule(null) })
    return () => { alive = false }
  }, [])
  const isAvatar = !!character && schedule?.avatar === character
  useEffect(() => {
    if (section === 'schedule' && !isAvatar) setSection('today')
  }, [section, isAvatar])

  const sections = useMemo(() => ([
    { id: 'today' as SectionId, icon: '☀️', label: t('Today') },
    { id: 'diary' as SectionId, icon: '📔', label: t('Diary') },
    { id: 'memories' as SectionId, icon: '🧠', label: t('Memories') },
    { id: 'bonds' as SectionId, icon: '🤝', label: t('Relationships') },
    { id: 'history' as SectionId, icon: '🕰️', label: t('History') },
    ...(isAvatar ? [{ id: 'schedule' as SectionId, icon: '🗓️', label: t('Daily schedule') }] : []),
    ...(withThoughts ? [{ id: 'thoughts' as SectionId, icon: '💭', label: t('Thoughts') }] : []),
  ]), [t, withThoughts, isAvatar])

  if (!character) {
    return <EmptyState icon="journal" title={t('No active character')} />
  }

  return (
    <div ref={rootRef} style={{ display: 'flex', gap: 10, height: '100%', minHeight: 0, fontSize: '0.88em' }}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 4, flex: '0 0 auto',
                    borderRight: '1px solid rgba(255,255,255,0.1)', paddingRight: narrow ? 6 : 8 }}>
        {sections.map((sec) => {
          const active = section === sec.id
          return (
            <button key={sec.id} title={sec.label}
              onClick={() => (sec.id === 'memories' ? openMemories('') : setSection(sec.id))}
              style={{
                display: 'flex', alignItems: 'center', gap: 7, cursor: 'pointer',
                padding: narrow ? '4px 6px' : '4px 9px', borderRadius: 7, textAlign: 'left',
                border: '1px solid ' + (active ? 'var(--accent,#6aa9ff)' : 'transparent'),
                background: active ? 'rgba(120,170,255,0.18)' : 'transparent',
                color: 'inherit', fontSize: '0.92em', opacity: active ? 1 : 0.65,
              }}>
              <span>{sec.icon}</span>
              {!narrow && <span>{sec.label}</span>}
            </button>
          )
        })}
      </div>
      <div style={{ flex: 1, minWidth: 0, minHeight: 0, overflow: section === 'today' ? 'auto' : 'hidden' }}>
        {section === 'today' && <TodayView character={character} onOpenMemories={() => openMemories('')} />}
        {section === 'diary' && <DiaryView key={character} character={character} canDeleteEntries={canDeleteEntries} />}
        {section === 'memories' && <MemoriesView character={character} initialRelated={memRelated} />}
        {section === 'bonds' && <BondsView character={character} onOpenMemories={openMemories} />}
        {section === 'history' && <HistoryView character={character} />}
        {section === 'schedule' && isAvatar && <ScheduleView data={schedule} />}
        {section === 'thoughts' && withThoughts && <MindThoughtsSection character={character} />}
      </div>
    </div>
  )
}
