/**
 * PosesTab — the editor for the two finite render-key axes.
 *
 * `pose` and `expression` are the ONLY keys under which image variants are
 * cached and animation clips are resolved. Free text never creates an entry:
 * text the resolver could not absorb lands in the CANDIDATES list below, and
 * grows the catalog only when an admin approves it — as a new entry or as a
 * synonym of an existing one.
 *
 * The animation vocabulary (pose axis only) is NOT hardcoded: the dropdown is
 * filled from the clips that actually exist (/assets/animation-clips).
 *
 * Catalog:    GET/POST /poses · PUT/DELETE /poses/{key}   (?axis=…)
 *             POST /poses/{key}/rename   (pose axis — every stored reference follows)
 * Candidates: GET /poses/candidates · POST /poses/candidates/approve|dismiss|dismiss_all
 * Images:     POST /poses/expression-images/clear
 *
 * Expressions use outfit-bound sets and a fixed image pose. Editing their
 * render prompts changes the contract; old images remain historical until
 * explicitly previewed cleanup. Pose/animation editing is independent.
 */
import { ConfirmDialog } from '@anima/player-ui'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { PoseAnimationDialog } from './PoseAnimationDialog'
import { ExpressionSetsEditor } from './ExpressionSetsEditor'
import type { PoseAnimationRequest } from './PoseAnimationDialog'
import { PoseAnimationChoice } from './PoseAnimationChoice'
import type { AnimationCandidate } from './PoseAnimationChoice'
import { ClipCatalog } from './ClipCatalog'
import { ClipInbox } from './ClipInbox'
import { ClipLibrary } from './ClipLibrary'
import { ClipTransitions } from './ClipTransitions'
import { clipCoverage, setLabel } from './clipSets'
import type { ClipListing } from './clipSets'
import { ClipPreview } from './ClipPreview'
import { useI18n } from '../../i18n/I18nProvider'
import { apiDelete, apiGet, apiPost, apiPut } from '../../lib/api'
import { useToast } from '../../lib/Toast'
import { Field } from '@anima/player-ui'
import { DetailToolbar } from '../../components/DetailToolbar'
import { ListHeader } from '../../components/ListHeader'
import { ListPane } from '../../components/ListPane'
import { CommaListInput } from '../../components/CommaListInput'
import { PromptDialog } from '../../components/PromptDialog'

type Axis = 'pose' | 'expression'
interface AnimationJob {
  task_id: string
  status: 'pending' | 'running' | 'completed' | 'failed' | 'cancelled'
  mode: PoseAnimationRequest['mode']
  key?: string | null
  phase?: string | null
  kind?: string | null
  error?: string | null
  /** awaiting_choice → published | discarded | expired (plan v3: variant choice) */
  state?: string | null
  candidates?: AnimationCandidate[] | null
  backend?: string | null
  generator?: string | null
  /** what was asked for — a retry reopens the dialog with it */
  request?: {
    mode: PoseAnimationRequest['mode']
    key: string
    text: string
    raw_text: string
    hint: string
    backend: string
    variants: number
  } | null
}

function activeJob(job: AnimationJob) {
  return job.status === 'pending' || job.status === 'running'
}

/** A job that ended without variants to pick — it can be retried or removed. */
function failedJob(job: AnimationJob) {
  return job.status === 'failed' || job.status === 'cancelled'
}

/** A finished job whose variants wait for the admin's pick. */
function awaitingChoice(job: AnimationJob) {
  return job.status === 'completed'
    && (job.state === 'awaiting_choice' || job.state === 'publishing')
}
/** The tab has five surfaces: the catalog entries, the installed clip library
 *  behind their animation kinds, the CMU clip pool those kinds come from, the
 *  inbox of foreign files waiting to be imported, and the bridge clips that
 *  have to play between two clips. */
type View = 'entries' | 'library' | 'catalog' | 'inbox' | 'transitions'

/** The label of each surface — the button row reads it, and a nested ternary
 *  over five cases reads like nothing at all. */
const VIEW_LABELS: Record<View, string> = {
  entries: 'Entries',
  library: 'Library',
  catalog: 'CMU clip catalog',
  inbox: 'Import files',
  transitions: 'Transitions',
}

/** One place type: the vocabulary a marker speaks. `root_drop` is a FRACTION
 *  of the figure height, so it reads back as metres against a 1.70 m figure.
 *  `needs_place` false means the poses of this type need no marker at all —
 *  they are offered "anywhere here", get no place assigned and their spot is
 *  never named (standing and ground-level poses). */
interface PlaceType {
  label: string
  root_drop: number
  default: string
  needs_place: boolean
  /** which layer the effective group comes from (server: `_store`) and, in
   *  the editable copy, which layer it is saved to (`store`) */
  _store?: Store
  store?: Store
}

interface Entry {
  key: string
  prompt: string
  label?: string
  label_de?: string
  label_de_missing?: boolean
  synonyms: string[]
  animation: string
  solo: boolean
  is_default?: boolean
  axis?: Axis
  /** place fields — pose axis only, an expression has no place */
  group?: string
  /** slots of the anchor marker a PAIR pose consumes (solo poses: always 1) */
  places?: 1 | 2
  /** degrees the pair clip's frame turns against the marker facing */
  yaw_offset?: number
  /** which layer the entry lives in: the tracked catalog file, or this
   *  world's own layer in its world.db for entries that must never be
   *  committed */
  store?: Store
  movement?: boolean
  deletable?: boolean
  resettable?: boolean
  /** false for the keys the server code names literally (pose axis) */
  renamable?: boolean
}

type Store = 'shared' | 'world'

interface CatalogData {
  entries: Entry[]
  kinds: string[]
  /** kinds that exist as a PAIR clip (two halves) — two-person poses */
  pair_kinds?: string[]
  /** Per pair kind: how far apart the two figures stand at the anchor moment,
   *  in metres, measured by the clip importer. A MARKER SLOT is 0.6 m wide,
   *  so this says how many slots the two bodies span — but not how much floor
   *  the pose sweeps, which is why it suggests and never decides. */
  pair_spans?: Record<string, number>
  /** place types, keyed by group id (pose axis only) */
  groups?: Record<string, PlaceType>
  problems: string[]
}

interface Candidate {
  raw_text: string
  nearest_key: string
  distance: number | null
  count: number
  first_seen: string
  last_seen: string
}

/** A marker slot, in metres — the default `spacing_m` of a place marker. */
const SLOT_WIDTH_M = 0.6

/** The slot count the clip's own measurement SUGGESTS: two bodies closer
 *  together than one slot fit on one. Only a suggestion — a dance sweeps far
 *  more floor than the distance between its dancers (salsa measures 0.39 m
 *  and still wants two slots), so the author has the last word. */
function suggestedPlaces(span: number | undefined): 1 | 2 | undefined {
  if (typeof span !== 'number') return undefined
  return span <= SLOT_WIDTH_M ? 1 : 2
}

const EMPTY: Entry = { key: '', prompt: '', synonyms: [], animation: '', solo: true,
  group: '', store: 'shared', label: '', label_de: '' }

/** Figure height the root drop is read back against — the reference figure of
 *  every metre readout in the admin UI. */
const REFERENCE_HEIGHT_M = 1.7

export function PosesTab() {
  const { t } = useI18n()
  const { toast } = useToast()
  const [axis, setAxis] = useState<Axis>('pose')
  const [expressionSet, setExpressionSet] = useState('humanoid')
  const [pendingSet, setPendingSet] = useState<string | null>(null)
  const [view, setView] = useState<View>('entries')
  const [data, setData] = useState<CatalogData>({ entries: [], kinds: [], problems: [] })
  const loadCounter = useRef(0)
  // The installed clips — the Library view lives off this, and the entry
  // editor reads the set coverage of the selected kind from it.
  const [clipList, setClipList] = useState<ClipListing>({ clips: [], kinds: [] })
  const [candidates, setCandidates] = useState<Candidate[]>([])
  const [selected, setSelected] = useState<string>('')
  const [draft, setDraft] = useState<Entry | null>(null)
  const [isNew, setIsNew] = useState(false)
  // raw_text of the candidate the open draft was started from ('' = plain new entry)
  const [approveOf, setApproveOf] = useState('')
  const [search, setSearch] = useState('')
  const [onlyMissing, setOnlyMissing] = useState(false)
  // '' = no place-type filter on the list
  const [groupFilter, setGroupFilter] = useState('')
  // Editable copy of the whole `groups` block — PUT /poses/groups replaces it
  // as a whole, so it is edited as a whole and saved with one button.
  const [groupsDraft, setGroupsDraft] = useState<Record<string, PlaceType>>({})
  const [newGroupKey, setNewGroupKey] = useState('')
  // The place-type editor is collapsed by default: it lives above the catalog
  // list in the narrow left column and would otherwise squeeze the list.
  const [showGroups, setShowGroups] = useState(false)
  const [confirmDismiss, setConfirmDismiss] = useState<string | null>(null)
  const [confirmDismissAll, setConfirmDismissAll] = useState(false)
  const [confirmClear, setConfirmClear] = useState(false)
  const [busy, setBusy] = useState(false)
  const [deleteOpen, setDeleteOpen] = useState(false)
  const [renameOpen, setRenameOpen] = useState(false)
  const [animationDialog, setAnimationDialog] = useState<PoseAnimationRequest | null>(null)
  const [animationJobs, setAnimationJobs] = useState<AnimationJob[]>([])
  const [jobsRefresh, setJobsRefresh] = useState(0)
  const jobStatuses = useRef(new Map<string, AnimationJob['status']>())
  const notifiedJobs = useRef(new Set<string>())
  const pendingCompletions = useRef(new Map<string, { job: AnimationJob; reload: Promise<void> }>())
  const [choiceJob, setChoiceJob] = useState<AnimationJob | null>(null)

  const isPose = axis === 'pose'

  const load = useCallback(async () => {
    const version = ++loadCounter.current
    try {
      const catalog = await apiGet<CatalogData>(`/poses?axis=${axis}&set_id=${axis === 'expression' ? encodeURIComponent(expressionSet) : ''}`)
      if (version !== loadCounter.current) return
      setData(catalog)
    } catch (e) {
      if (version === loadCounter.current) toast(t('Error') + ': ' + (e as Error).message, 'error')
    }
    try {
      const r = await apiGet<{ candidates: Candidate[] }>(`/poses/candidates?axis=${axis}&set_id=${axis === 'expression' ? encodeURIComponent(expressionSet) : ''}`)
      if (version !== loadCounter.current) return
      setCandidates(r.candidates || [])
    } catch {
      if (version === loadCounter.current) setCandidates([])
    }
  }, [axis, expressionSet, t, toast])

  /** The clip listing does not depend on the axis — it is the file state of
   *  the shared libraries, reloaded after every rename/move/delete. */
  const loadClips = useCallback(async () => {
    try {
      setClipList(await apiGet<ClipListing>('/assets/animation-clips'))
    } catch {
      setClipList({ clips: [], kinds: [] })
    }
  }, [])

  useEffect(() => {
    load()
  }, [load])

  useEffect(() => {
    void loadClips()
  }, [loadClips])

  /** After a write in the Library view: the files AND the catalog (a renamed
   *  kind changes which poses still have a clip). */
  const reloadLibrary = useCallback(async () => {
    await loadClips()
    await load()
  }, [load, loadClips])

  useEffect(() => {
    let disposed = false
    let timer: ReturnType<typeof setTimeout> | undefined
    const drainPendingCompletions = async () => {
      const pending = [...pendingCompletions.current.values()]
      if (pending.length) {
        await Promise.all(pending.map(({ reload }) => reload))
        if (disposed) return
        const ready = pending.map(({ job }) => job)
        if (axis === 'pose') {
          setDraft((current) => {
            const job = ready.find((item) => item.key === current?.key && item.state === 'published')
            return current && job?.kind ? { ...current, animation: job.kind } : current
          })
        }
        for (const job of ready) {
          toast((awaitingChoice(job) ? t('Variants ready — choose one') : t('Animation ready'))
            + (job.key ? `: ${job.key}` : ''))
          notifiedJobs.current.add(job.task_id)
          pendingCompletions.current.delete(job.task_id)
        }
      }
    }
    const poll = async () => {
      try {
        await drainPendingCompletions()
        if (disposed) return
        const result = await apiGet<{ jobs: AnimationJob[] }>('/poses/animations/jobs')
        if (disposed) return
        setAnimationJobs(result.jobs)
        const completed = result.jobs.filter((job) => job.status === 'completed'
          && !notifiedJobs.current.has(job.task_id)
          && !pendingCompletions.current.has(job.task_id)
          && (jobStatuses.current.get(job.task_id) === 'pending'
            || jobStatuses.current.get(job.task_id) === 'running'))
        for (const job of result.jobs) jobStatuses.current.set(job.task_id, job.status)
        if (completed.length) {
          // Share the reload across effect restarts; keep completions pending
          // until a live poll has reconciled the draft and shown every toast.
          const reload = reloadLibrary()
          for (const job of completed) pendingCompletions.current.set(job.task_id, { job, reload })
        }
        await drainPendingCompletions()
        if (disposed) return
        if (result.jobs.some(activeJob) || pendingCompletions.current.size > 0) timer = setTimeout(() => { void poll() }, 4000)
      } catch (error) {
        if (disposed) return
        toast(t('Error') + ': ' + (error as Error).message, 'error')
        // Retry while active jobs or unreconciled completions remain.
        if (pendingCompletions.current.size > 0
          || [...jobStatuses.current.values()].some((status) => status === 'pending' || status === 'running')) {
          timer = setTimeout(() => { void poll() }, 4000)
        }
      }
    }
    void poll()
    return () => { disposed = true; clearTimeout(timer) }
  }, [axis, jobsRefresh, reloadLibrary, t, toast])

  const closeAnimationDialog = useCallback(() => setAnimationDialog(null), [])
  const animationStarted = (taskId: string, request: PoseAnimationRequest) => {
    jobStatuses.current.set(taskId, 'pending')
    setAnimationJobs((jobs) => [{ task_id: taskId, status: 'pending', mode: request.mode,
      key: request.entryKey }, ...jobs])
    setAnimationDialog(null)
    setJobsRefresh((value) => value + 1)
    if (request.mode === 'candidate' && request.rawText === approveOf) {
      setDraft(null)
      setSelected('')
      setIsNew(false)
      setApproveOf('')
    }
  }

  /** The dialog request that repeats a failed job, or null when it cannot be
   *  repeated (its catalog entry is gone or is a pair pose). */
  const retryRequest = (job: AnimationJob): PoseAnimationRequest | null => {
    const asked = job.request
    if (!asked) return null
    const preset = { initialHint: asked.hint, initialModel: asked.backend,
      initialVariants: asked.variants }
    if (asked.mode === 'entry') {
      const entry = data.entries.find((item) => item.key === asked.key && item.solo !== false)
      return entry ? { mode: 'entry', entryKey: entry.key, prompt: entry.prompt, ...preset } : null
    }
    if (asked.mode === 'candidate') {
      return asked.raw_text ? { mode: 'candidate', rawText: asked.raw_text, ...preset } : null
    }
    return asked.text ? { mode: 'free', initialText: asked.text, ...preset } : null
  }

  const dismissJob = async (job: AnimationJob) => {
    try {
      await apiPost(`/poses/animations/${job.task_id}/dismiss`, {})
      setAnimationJobs((jobs) => jobs.filter((item) => item.task_id !== job.task_id))
      jobStatuses.current.delete(job.task_id)
    } catch (error) {
      toast(t('Error') + ': ' + (error as Error).message, 'error')
    }
  }

  const phaseLabel = (phase: string | null | undefined) => {
    switch (phase) {
      case 'llm': return t('writing captions')
      case 'hub': return t('animating')
      case 'convert': return t('converting')
      case 'import': return t('importing')
      case 'check': return t('checking')
      case 'publish': return t('publishing')
      case 'choose': return t('waiting for your choice')
      default: return phase || t('pending')
    }
  }

  const jobStatus = (job: AnimationJob) => awaitingChoice(job) ? (
    <div role="status" style={{ display: 'flex', gap: 6, alignItems: 'center', flexWrap: 'wrap' }}>
      <button type="button" className="ga-btn ga-btn-sm ga-btn-primary" onClick={() => setChoiceJob(job)}>
        {t('Choose variant ({n})').replace('{n}',
          String((job.candidates || []).filter((cand) => cand.ok).length))}
      </button>
    </div>
  ) : job.state === 'expired' ? (
    <div role="status"><span className="ga-tag">{t('Variants expired')}</span></div>
  ) : (
    <div role="status" style={{ display: 'flex', gap: 6, alignItems: 'center', flexWrap: 'wrap' }}>
      <span className="ga-tag">
        {activeJob(job)
          ? t('Generating … ({phase})').replace('{phase}', phaseLabel(job.phase))
          : t('Failed: {error}').replace('{error}', job.error || t('Unknown error'))}
      </span>
      {failedJob(job) ? (() => {
        const retry = retryRequest(job)
        return <>
          {retry ? (
            <button type="button" className="ga-btn ga-btn-sm" onClick={() => setAnimationDialog(retry)}>
              {t('Retry')}
            </button>
          ) : null}
          <button type="button" className="ga-btn ga-btn-sm" onClick={() => { void dismissJob(job) }}>
            {t('Remove')}
          </button>
        </>
      })() : null}
    </div>
  )

  const jobsByKey = new Map<string, AnimationJob>()
  for (const job of animationJobs) {
    if (job.key && !jobsByKey.has(job.key)) jobsByKey.set(job.key, job)
  }

  // Switching the axis drops the open draft — the two catalogs share no keys.
  useEffect(() => {
    setDraft(null)
    setSelected('')
    setIsNew(false)
    setApproveOf('')
    setConfirmDismiss(null)
    setConfirmDismissAll(false)
    setGroupFilter('')
  }, [axis, expressionSet])

  // The server is the truth for the place types: every (re)load restarts the
  // editable copy from what was just fetched.
  useEffect(() => {
    // The server says where each effective group COMES FROM (`_store`); the
    // draft carries where it GOES (`store`), which starts out the same.
    setGroupsDraft(Object.fromEntries(
      Object.entries(data.groups || {}).map(([k, g]) => [k, { ...g, store: g._store || 'shared' }]),
    ))
    setNewGroupKey('')
  }, [data.groups])

  const list = useMemo(() => {
    const q = search.trim().toLowerCase()
    return data.entries.filter((p) => {
      if (isPose && onlyMissing && p.animation) return false
      if (isPose && groupFilter && (p.group || '') !== groupFilter) return false
      if (!q) return true
      return (
        p.key.includes(q) ||
        p.prompt.toLowerCase().includes(q) ||
        p.synonyms.some((s) => s.includes(q))
      )
    })
  }, [data.entries, search, onlyMissing, groupFilter, isPose])

  const missingCount = useMemo(
    () => data.entries.filter((p) => !p.animation).length,
    [data.entries],
  )

  const select = useCallback(
    (key: string) => {
      const p = data.entries.find((x) => x.key === key)
      if (!p) return
      setSelected(key)
      setIsNew(false)
      setApproveOf('')
      setDraft({ ...p, synonyms: [...p.synonyms] })
    },
    [data.entries],
  )

  const addNew = useCallback(() => {
    setSelected('')
    setIsNew(true)
    setApproveOf('')
    setDraft({ ...EMPTY })
  }, [])

  /** "Create pose entry" out of the catalog browser: back to the entry editor
   *  with a fresh pose draft whose animation is the kind just imported. The
   *  axis is already 'pose' — switching INTO the catalog forces it, so the
   *  axis-change effect below cannot wipe the draft right after it was set. */
  const startFromClip = useCallback(
    // `store` is what the importer knows and this form cannot: a clip that
    // went into the LICENSED library is licensed or adult material, and its
    // catalog entry belongs in this world's layer, not in a committed file.
    async (animation: string, store: Store = 'shared') => {
      setView('entries')
      setSelected('')
      setIsNew(true)
      setApproveOf('')
      setDraft({ ...EMPTY, key: animation, animation, store })
      await load()
    },
    [load],
  )

  const startApprove = useCallback((c: Candidate) => {
    setSelected('')
    setIsNew(true)
    setApproveOf(c.raw_text)
    setDraft({ ...EMPTY, key: c.raw_text })
  }, [])

  const save = useCallback(async () => {
    if (!draft) return
    const key = draft.key.trim().toLowerCase()
    if (!key || !draft.prompt.trim()) {
      toast(t('Key and prompt text are required'), 'error')
      return
    }
    if (isPose && !draft.animation.trim()) {
      toast(t('An animation kind is required for poses'), 'error')
      return
    }
    if (isPose && !draft.group) {
      toast(t('A place type is required for poses'), 'error')
      return
    }
    // A pair pose has no sensible default slot count. It used to fall back to
    // 2 silently, which is how every pair pose in the catalog ended up
    // claiming two slots — including the ones whose bodies lie 6 cm apart and
    // fit on any single bed.
    if (isPose && draft.solo === false && draft.places !== 1 && draft.places !== 2) {
      toast(t('Choose how many marker slots this pair pose uses'), 'error')
      return
    }
    try {
      const body = {
        axis,
        set_id: isPose ? '' : expressionSet,
        key,
        prompt: draft.prompt,
        synonyms: draft.synonyms,
        label: draft.label || key,
        ...(isPose ? { label_de: draft.label_de || '' } : {}),
        store: draft.store || 'shared',
        ...(isPose
          ? {
              animation: draft.animation,
              solo: draft.solo,
              group: draft.group,
              // Pair fields only: a solo pose occupies one place and never
              // turns, and the server drops them again when solo is set.
              ...(draft.solo
                ? {}
                : { places: draft.places, yaw_offset: draft.yaw_offset ?? 0 }),
            }
          : {}),
      }
      if (approveOf) {
        await apiPost('/poses/candidates/approve', { ...body, raw_text: approveOf })
        toast(t('Candidate approved'))
      } else if (isNew) {
        await apiPost('/poses', body)
        toast(t('Saved'))
      } else {
        await apiPut(`/poses/${encodeURIComponent(key)}?axis=${axis}`, body)
        toast(t('Saved'))
      }
      setIsNew(false)
      setApproveOf('')
      setSelected(key)
      await load()
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    }
  }, [approveOf, axis, expressionSet, draft, isNew, isPose, load, t, toast])

  const remove = useCallback(async () => {
    if (!draft || isNew || (draft.deletable === false && !draft.resettable)) return
    try {
      await apiDelete(`/poses/${encodeURIComponent(draft.key)}?axis=${axis}&set_id=${axis === 'expression' ? encodeURIComponent(expressionSet) : ''}`)
      toast(draft.resettable ? t('Override reset') : t('Deleted'))
      setDeleteOpen(false)
      await loadClips()
      setDraft(null)
      setSelected('')
      await load()
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    }
  }, [axis, expressionSet, draft, isNew, load, loadClips, t, toast])

  /** Renames the selected pose's KEY. The server rewrites every stored
   *  reference of this world (character poses, pair interactions, invites,
   *  candidates, rendered variants); the draft keeps any unsaved edit. */
  const renameKey = useCallback(
    async (value: string) => {
      if (!draft || isNew) return
      const oldKey = draft.key
      const newKey = value.trim().toLowerCase()
      setRenameOpen(false)
      if (!newKey || newKey === oldKey) return
      try {
        const r = await apiPost<{ key: string; references: { failed: string[] } }>(
          `/poses/${encodeURIComponent(oldKey)}/rename?axis=${axis}`,
          { new_key: newKey, set_id: isPose ? '' : expressionSet },
        )
        toast(t('Key renamed') + `: ${oldKey} → ${r.key}`)
        if (r.references?.failed?.length) {
          toast(t('Not updated for') + ': ' + r.references.failed.join(', '), 'error')
        }
        setDraft((d) => (d ? { ...d, key: r.key,
          synonyms: d.synonyms.filter((s) => s !== r.key) } : d))
        setSelected(r.key)
        await loadClips()
        await load()
      } catch (e) {
        toast(t('Error') + ': ' + (e as Error).message, 'error')
      }
    },
    [axis, expressionSet, isPose, draft, isNew, load, loadClips, t, toast],
  )

  const asSynonym = useCallback(
    async (c: Candidate, target: string) => {
      if (!target || busy) return
      setBusy(true)
      try {
        await apiPost('/poses/candidates/approve', {
          axis,
          set_id: isPose ? '' : expressionSet,
          raw_text: c.raw_text,
          as_synonym_of: target,
        })
        toast(t('Added as synonym') + `: ${target}`)
        await load()
      } catch (e) {
        toast(t('Error') + ': ' + (e as Error).message, 'error')
      } finally {
        setBusy(false)
      }
    },
    [axis, expressionSet, isPose, busy, load, t, toast],
  )

  const dismiss = useCallback(
    async (c: Candidate) => {
      if (busy) return
      setBusy(true)
      try {
        await apiPost('/poses/candidates/dismiss', { axis, set_id: isPose ? '' : expressionSet, raw_text: c.raw_text })
        setCandidates((prev) => prev.filter((x) => x.raw_text !== c.raw_text))
        setConfirmDismiss(null)
      } catch (e) {
        toast(t('Error') + ': ' + (e as Error).message, 'error')
      } finally {
        setBusy(false)
      }
    },
    [axis, expressionSet, isPose, busy, t, toast],
  )

  const dismissAll = useCallback(async () => {
    if (busy) return
    setBusy(true)
    try {
      const r = await apiPost<{ dismissed: number }>('/poses/candidates/dismiss_all', { axis, set_id: isPose ? '' : expressionSet })
      setCandidates([])
      setConfirmDismissAll(false)
      toast(t('Dismissed {n} candidates').replace('{n}', String(r.dismissed)))
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    } finally {
      setBusy(false)
    }
  }, [axis, expressionSet, isPose, busy, t, toast])

  const clearExpressionImages = useCallback(async () => {
    if (busy) return
    setBusy(true)
    try {
      const r = await apiPost<{ images_deleted?: number }>(
        '/poses/expression-images/clear',
        {},
      )
      toast(`${t('Rendered expression images cleared')}: ${r?.images_deleted ?? 0}`)
      setConfirmClear(false)
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    } finally {
      setBusy(false)
    }
  }, [busy, t, toast])

  const upd = useCallback(<K extends keyof Entry>(k: K, v: Entry[K]) => {
    setDraft((prev) => (prev ? { ...prev, [k]: v } : prev))
  }, [])

  // ── Place types ────────────────────────────────────────────────────────
  /** How many catalog entries name each place type — a type still in use
   *  cannot be removed, because its poses would become unplaceable. */
  const groupUsage = useMemo(() => {
    const out: Record<string, number> = {}
    for (const p of data.entries) {
      const g = p.group || ''
      if (g) out[g] = (out[g] || 0) + 1
    }
    return out
  }, [data.entries])

  const patchGroup = useCallback((key: string, patch: Partial<PlaceType>) => {
    setGroupsDraft((prev) =>
      prev[key] ? { ...prev, [key]: { ...prev[key], ...patch } } : prev,
    )
  }, [])

  const addGroup = useCallback(() => {
    const key = newGroupKey.trim().toLowerCase()
    if (!key) {
      toast(t('A key is required for a place type'), 'error')
      return
    }
    if (groupsDraft[key]) {
      toast(t('This place type already exists'), 'error')
      return
    }
    setGroupsDraft((prev) => ({
      ...prev,
      [key]: { label: key, root_drop: 0, default: '', needs_place: true, store: 'shared' },
    }))
    setNewGroupKey('')
  }, [groupsDraft, newGroupKey, t, toast])

  const removeGroup = useCallback((key: string) => {
    setGroupsDraft((prev) => {
      const next = { ...prev }
      delete next[key]
      return next
    })
  }, [])

  const saveGroups = useCallback(async () => {
    try {
      await apiPut('/poses/groups', { groups: groupsDraft })
      toast(t('Saved'))
      await load()
    } catch (e) {
      toast(t('Error') + ': ' + (e as Error).message, 'error')
    }
  }, [groupsDraft, load, t, toast])

  /** The `root_drop` of one place type, as a FRACTION of the figure height —
   *  0 for an unknown or empty one. The clip surfaces calibrate their preview
   *  against a place type's body, and the figure has to sit as far under the
   *  marked surface as the server will put it. */
  const rootDropOf = useCallback(
    (group: string) => (data.groups || {})[group]?.root_drop ?? 0,
    [data.groups],
  )

  const transitionCount = isPose && draft
    ? (clipList.transitions || []).filter((rule) => rule.from === draft.key || rule.to === draft.key).length
    : 0

  const viewSwitch = (
    <div style={{ display: 'flex', gap: 6, marginBottom: 10 }}>
      {(['entries', 'library', 'catalog', 'inbox', 'transitions'] as View[]).map((v) => (
        <button
          key={v}
          type="button"
          className={`ga-btn ga-btn-sm${view === v ? ' ga-btn-primary' : ''}`}
          onClick={() => {
            // Every other surface is about POSE animations — pinning the axis
            // here keeps "create pose entry" (and the Library's "Used by")
            // from landing on the expression catalog, and out of reach of the
            // axis-change reset.
            if (v !== 'entries') setAxis('pose')
            setView(v)
          }}
        >
          {t(VIEW_LABELS[v])}
        </button>
      ))}
    </div>
  )

  if (view === 'library') {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}>
        {viewSwitch}
        <ClipLibrary listing={clipList} poses={data.entries} onReload={reloadLibrary}
          rootDropOf={rootDropOf} />
      </div>
    )
  }

  if (view === 'transitions') {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}>
        {viewSwitch}
        <ClipTransitions poses={data.entries} onSaved={() => { void loadClips() }} />
      </div>
    )
  }

  if (view === 'catalog' || view === 'inbox') {
    // Full-height column: the browser's panes scroll on their own inside it
    // (facets, list, preview+import), the page itself does not — otherwise
    // the import button sat below the browser's bottom edge.
    return (
      <div style={{ display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}>
        {viewSwitch}
        {view === 'catalog'
          ? <ClipCatalog onCreatePose={startFromClip} rootDropOf={rootDropOf} />
          : <ClipInbox onCreatePose={startFromClip} rootDropOf={rootDropOf} />}
      </div>
    )
  }

  return (
    // The view switch sits ABOVE the two columns, not inside the list pane:
    // collapsing the pane must not take the way back to Library/Import with it.
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}>
      {viewSwitch}
      {!isPose && <ExpressionSetsEditor selected={expressionSet}
        reloadKey={data.entries.map(e => e.key).join(',')} onSaved={load}
        labels={Object.fromEntries(data.entries.map(e => [e.key, e.label || e.key]))}
        worldOnlyMembers={data.entries.filter(e => e.store === 'world' && !e.resettable).map(e => e.key)}
        onSelect={id => {
          const original = data.entries.find(e => e.key === selected)
          if (draft && (isNew || JSON.stringify(draft) !== JSON.stringify(original))) setPendingSet(id)
          else setExpressionSet(id)
        }} />}
      <div className="ga-twocol">
        <ListPane id="poses" label={t('Catalog')}>
            <ListHeader
            title={t('Catalog')}
            onNew={addNew}
            extra={
              confirmClear ? (
                <>
                  <button
                    type="button"
                    className="ga-btn ga-btn-sm ga-btn-danger"
                    disabled={busy}
                    onClick={clearExpressionImages}
                  >
                    {busy ? t('Clearing…') : t('Really clear?')}
                  </button>
                  <button
                    type="button"
                    className="ga-btn ga-btn-sm"
                    onClick={() => setConfirmClear(false)}
                  >
                    {t('Cancel')}
                  </button>
                </>
              ) : (
                <button
                  type="button"
                  className="ga-btn ga-btn-sm ga-btn-danger"
                  title={t('Deletes all expression images. To remove only incompatible history, use the per-character cleanup preview.')}
                  onClick={() => setConfirmClear(true)}
                >
                  {t('Clear rendered expression images')}
                </button>
              )
            }
          />
          <p className="ga-sched-muted">
            {t('The catalog is the closed set of render keys: a pose key carries the body-posture prompt and the animation kind, an expression key the facial prompt. Free text is matched onto a key — it never creates one.')}
          </p>

          <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
            {(['pose', 'expression'] as Axis[]).map((a) => (
              <button
                key={a}
                type="button"
                className={`ga-btn ga-btn-sm${axis === a ? ' ga-btn-primary' : ''}`}
                onClick={() => setAxis(a)}
              >
                {a === 'pose' ? t('Poses') : t('Expressions')}
              </button>
            ))}
          </div>

          {data.problems.length ? (
            <div className="ga-form-hint" style={{ color: 'var(--warn, #d29922)' }}>
              {data.problems.map((p) => (
                <div key={p}>⚠ {p}</div>
              ))}
            </div>
          ) : null}

          {/* Place types — the finite vocabulary a marker speaks. Collapsed by
              default so it does not eat the catalog list's height; opened, it
              scrolls INSIDE a capped box (the column has no scrollbar of its
              own, so a full-height block would push the two lists below it out
              of view). */}
          {isPose ? (
            <div style={{ marginBottom: 8, flex: '0 0 auto' }}>
              <button
                type="button"
                className="ga-btn ga-btn-sm"
                style={{ width: '100%' }}
                onClick={() => setShowGroups((v) => !v)}
              >
                {showGroups ? '▾' : '▸'} {t('Place types')} ({Object.keys(groupsDraft).length})
              </button>
              {showGroups ? (
                <div style={{ marginTop: 6, maxHeight: '40vh', overflowY: 'auto', paddingRight: 4 }}>
                  <p className="ga-form-hint" style={{ margin: '0 0 6px' }}>
                    {t('A marker names a place type; every pose belongs to exactly one. Root drop × 1.70 m is how far a figure’s root sinks below the marked surface.')}
                  </p>
                  {Object.entries(groupsDraft).map(([key, g]) => {
                    const used = groupUsage[key] || 0
                    const poses = data.entries.filter((p) => (p.group || '') === key)
                    return (
                      <div key={key} className="ga-fieldset">
                        <div
                          className="ga-fieldset-title"
                          style={{ display: 'flex', alignItems: 'center', gap: 6 }}
                        >
                          <code style={{ flex: 1 }}>{key}</code>
                          <button
                            type="button"
                            className="ga-btn ga-btn-sm ga-btn-danger"
                            disabled={used > 0}
                            title={
                              used
                                ? `${t('Still in use — reassign these poses first')} (${used})`
                                : t('Remove this place type')
                            }
                            onClick={() => removeGroup(key)}
                          >
                            ×
                          </button>
                        </div>
                        <Field label={t('Label')}>
                          <input
                            className="ga-input"
                            value={g.label}
                            onChange={(e) => patchGroup(key, { label: e.target.value })}
                          />
                        </Field>
                        <Field
                          label={t('Root drop')}
                          hint={`× 1.70 m = ${(g.root_drop * REFERENCE_HEIGHT_M).toFixed(2)} m`}
                        >
                          <input
                            className="ga-input"
                            type="number"
                            min={0}
                            max={1}
                            step={0.001}
                            value={g.root_drop}
                            onChange={(e) =>
                              patchGroup(key, { root_drop: Number(e.target.value) })
                            }
                          />
                        </Field>
                        <Field
                          label={t('Needs a marker')}
                          hint={t('On: a pose of this type is only possible where a marker of it stands. Off: the poses are offered anywhere in the room, take no place and their spot is never named.')}
                        >
                          <label style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                            <input
                              type="checkbox"
                              checked={g.needs_place !== false}
                              onChange={(e) =>
                                patchGroup(key, { needs_place: e.target.checked })
                              }
                            />
                            <span style={{ fontSize: '0.85em', opacity: 0.75 }}>
                              {g.needs_place !== false
                                ? t('a marker is required')
                                : t('no marker needed')}
                            </span>
                          </label>
                        </Field>
                        <Field
                          label={t('Stored in')}
                          hint={t('The shared catalog travels with the repository; this world keeps its own version in its world.db, which overrides the shared one for the same key and is never committed.')}
                        >
                          <select
                            className="ga-input"
                            value={g.store || 'shared'}
                            onChange={(e) => patchGroup(key, { store: e.target.value as Store })}
                          >
                            <option value="shared">{t('shared catalog (committed)')}</option>
                            <option value="world">{t('this world (never committed)')}</option>
                          </select>
                        </Field>
                        <Field
                          label={t('Default pose')}
                          hint={t('The pose a click on such a marker sets. It has to be a pose of this place type — only a place type without poses may stay empty.')}
                        >
                          <select
                            className="ga-input"
                            value={g.default}
                            onChange={(e) => patchGroup(key, { default: e.target.value })}
                          >
                            {!poses.length ? (
                              // A place type only just added has no poses yet: a
                              // pose can only name a type that already exists, so
                              // the default arrives with the first pose.
                              <option value="">{t('— none —')}</option>
                            ) : !g.default ? (
                              // With poses the server demands a real default —
                              // show the gap instead of silently rendering the
                              // first pose while the value is still empty.
                              <option value="" disabled>
                                {t('— pick a default pose —')}
                              </option>
                            ) : null}
                            {poses.map((p) => (
                              <option key={p.key} value={p.key}>
                                {p.key}
                              </option>
                            ))}
                          </select>
                        </Field>
                      </div>
                    )
                  })}
                  <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                    <input
                      className="ga-input"
                      style={{ flex: 1, minWidth: 90 }}
                      placeholder={t('new key')}
                      value={newGroupKey}
                      onChange={(e) => setNewGroupKey(e.target.value)}
                    />
                    <button type="button" className="ga-btn ga-btn-sm" onClick={addGroup}>
                      + {t('Place type')}
                    </button>
                    <button
                      type="button"
                      className="ga-btn ga-btn-sm ga-btn-primary"
                      onClick={saveGroups}
                    >
                      {t('Save place types')}
                    </button>
                  </div>
                </div>
              ) : null}
            </div>
          ) : null}

          <div style={{ display: 'flex', flexDirection: 'column', gap: 6, marginBottom: 8 }}>
            {isPose ? <>
              <button type="button" className="ga-btn ga-btn-sm"
                onClick={() => setAnimationDialog({ mode: 'free' })}>
                {t('New from description')}
              </button>
              {animationJobs.filter((job) => {
                const hasEntry = data.entries.some((entry) => entry.key === job.key)
                // An entry row shows only its NEWEST job; every other job still
                // waiting for a choice stays reachable here.
                const inRow = hasEntry && jobsByKey.get(job.key || '')?.task_id === job.task_id
                return (!hasEntry && (activeJob(job) || failedJob(job)))
                  || (awaitingChoice(job) && !inRow)
              }).map((job) => (
                <div key={job.task_id} style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                  {job.key ? <code>{job.key}</code> : null}{jobStatus(job)}
                </div>
              ))}
            </> : null}
            <input
              className="ga-input"
              placeholder={t('Search…')}
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
            {isPose ? (
              <label style={{ display: 'flex', gap: 6, alignItems: 'center', fontSize: '0.8em' }}>
                <input
                  type="checkbox"
                  checked={onlyMissing}
                  onChange={(e) => setOnlyMissing(e.target.checked)}
                />
                <span>
                  {t('Without animation')} ({missingCount})
                </span>
              </label>
            ) : null}
            {isPose && Object.keys(data.groups || {}).length ? (
              <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
                {Object.entries(data.groups || {}).map(([key, g]) => (
                  <button
                    key={key}
                    type="button"
                    className={`ga-btn ga-btn-sm${groupFilter === key ? ' ga-btn-primary' : ''}`}
                    title={`${g.label} (${groupUsage[key] || 0})`}
                    // clicking the active chip clears the filter again
                    onClick={() => setGroupFilter((prev) => (prev === key ? '' : key))}
                  >
                    {g.label || key}
                  </button>
                ))}
              </div>
            ) : null}
          </div>

          <ul className="ga-list">
            {!list.length ? <li className="ga-list-empty">{t('No entries')}</li> : null}
            {list.map((p) => (
              <li key={p.key}>
                <button
                  type="button"
                  className={`ga-list-row${selected === p.key ? ' is-active' : ''}`}
                  onClick={() => select(p.key)}
                >
                  <span className="ga-list-row-main">
                    {isPose ? <code>{p.key}</code> : <span title={p.key}>{p.label || p.key}</span>}
                    {isPose ? (
                      <span
                        className="ga-list-row-sub"
                        style={{ opacity: p.animation && p.group ? 1 : 0.4 }}
                      >
                        — {p.animation || t('no animation')} ·{' '}
                        {p.group || t('no place type')}
                      </span>
                    ) : null}
                  </span>
                  {isPose && data.pair_kinds?.includes(p.animation) ? (
                    <span className="ga-source" title={t('Pair animation — needs a partner')}>
                      {t('pair')}
                    </span>
                  ) : null}
                  {isPose && p.label_de_missing ? (
                    <span className="ga-source">{t('No German label')}</span>
                  ) : null}
                  {p.movement ? <span className="ga-source">{t('movement')}</span> : null}
                  {p.is_default ? <span className="ga-source">{t('default')}</span> : null}
                  {p.store === 'world'
                    ? <span className="ga-source">{t('world')}</span> : null}
                </button>
                {isPose && jobsByKey.has(p.key) && (() => {
                  const job = jobsByKey.get(p.key)!
                  return activeJob(job) || failedJob(job) || awaitingChoice(job) ? jobStatus(job) : null
                })()}
              </li>
            ))}
          </ul>

          {/* Candidates: free text the resolver could not absorb. A capped flex
              column so a long candidate list scrolls by itself and leaves the
              catalog list above its share of the column. */}
          <div
            style={{
              marginTop: 16, display: 'flex', flexDirection: 'column',
              flex: '0 1 auto', minHeight: 0, maxHeight: '35vh',
            }}
          >
            <div
              style={{
                display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                gap: 8, marginBottom: 4,
              }}
            >
              <h4 style={{ margin: 0 }}>
                {t('Candidates')} ({candidates.length})
              </h4>
              {candidates.length > 0 && !confirmDismissAll && (
                <button
                  type="button"
                  className="ga-btn ga-btn-sm"
                  disabled={busy}
                  onClick={() => setConfirmDismissAll(true)}
                >
                  {t('Dismiss all')}
                </button>
              )}
            </div>
            {confirmDismissAll && candidates.length > 0 && (
              <div
                style={{
                  display: 'flex', gap: 6, alignItems: 'center',
                  flexWrap: 'wrap', marginBottom: 6,
                }}
              >
                <span style={{ fontSize: '0.82em' }}>
                  {t('Dismiss all {n} open candidates?').replace('{n}', String(candidates.length))}
                </span>
                <button
                  type="button"
                  className="ga-btn ga-btn-sm ga-btn-danger"
                  disabled={busy}
                  onClick={dismissAll}
                >
                  {t('Yes, dismiss')}
                </button>
                <button
                  type="button"
                  className="ga-btn ga-btn-sm"
                  onClick={() => setConfirmDismissAll(false)}
                >
                  {t('Cancel')}
                </button>
              </div>
            )}
            <p className="ga-sched-muted" style={{ marginTop: 0 }}>
              {t('Free text that landed on the default key. Approve it as its own entry, attach it as a synonym, or dismiss it. "Seen" counts first sightings per server run.')}
            </p>
            {!candidates.length ? (
              <div className="ga-list-empty">{t('No open candidates')}</div>
            ) : (
              <ul className="ga-list">
                {candidates.map((c) => (
                  <li
                    key={c.raw_text}
                    style={{
                      display: 'flex',
                      flexDirection: 'column',
                      gap: 4,
                      padding: '6px 0',
                      borderBottom: '1px solid var(--border, #30363d)',
                    }}
                  >
                    <div style={{ display: 'flex', justifyContent: 'space-between', gap: 8 }}>
                      <code style={{ wordBreak: 'break-word' }}>{c.raw_text}</code>
                      <span style={{ fontSize: '0.75em', opacity: 0.6, whiteSpace: 'nowrap' }}>
                        {t('seen')} {c.count}× · {t('nearest')}: {c.nearest_key || '–'}
                      </span>
                    </div>
                    {confirmDismiss === c.raw_text ? (
                      <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                        <span style={{ fontSize: '0.82em' }}>{t('Dismiss this candidate?')}</span>
                        <button
                          type="button"
                          className="ga-btn ga-btn-sm ga-btn-danger"
                          disabled={busy}
                          onClick={() => dismiss(c)}
                        >
                          {t('Dismiss')}
                        </button>
                        <button
                          type="button"
                          className="ga-btn ga-btn-sm"
                          onClick={() => setConfirmDismiss(null)}
                        >
                          {t('Cancel')}
                        </button>
                      </div>
                    ) : (
                      <div style={{ display: 'flex', gap: 6, alignItems: 'center', flexWrap: 'wrap' }}>
                        <button
                          type="button"
                          className="ga-btn ga-btn-sm"
                          onClick={() => startApprove(c)}
                        >
                          {t('Approve')}
                        </button>
                        <select
                          className="ga-input"
                          style={{ maxWidth: 180 }}
                          value=""
                          disabled={busy}
                          onChange={(e) => asSynonym(c, e.target.value)}
                        >
                          <option value="">{t('As synonym of…')}</option>
                          {data.entries.map((p) => (
                            <option key={p.key} value={p.key}>
                              {p.key}
                            </option>
                          ))}
                        </select>
                        <button
                          type="button"
                          className="ga-btn ga-btn-sm"
                          onClick={() => setConfirmDismiss(c.raw_text)}
                        >
                          {t('Dismiss')}
                        </button>
                      </div>
                    )}
                  </li>
                ))}
              </ul>
            )}
          </div>
        </ListPane>

        <section className="ga-twocol-right">
          {!draft ? (
            <div className="ga-placeholder">{t('Pick an entry or create a new one.')}</div>
          ) : (
            <>
              <DetailToolbar
                title={
                  approveOf
                    ? `${t('Approve candidate')}: ${approveOf}`
                    : isNew
                      ? isPose
                        ? t('New pose')
                        : t('New expression')
                      : draft.key
                }
                onSave={save}
                onDelete={isNew || draft.deletable === false || draft.resettable ? undefined : () => setDeleteOpen(true)}
              />
              {!isNew && draft.resettable && <button type="button" className="ga-btn ga-btn-sm"
                onClick={() => setDeleteOpen(true)}>{t('Reset World override')}</button>}
              {/* Two columns: the catalog text on the left, the 3D animation
                  with its preview on the right — the preview needs the room. */}
              <div className="ga-form" style={{ display: 'grid',
                gridTemplateColumns: isPose ? 'minmax(260px, 1fr) minmax(320px, 1.2fr)' : '1fr',
                gap: 16, alignItems: 'start' }}>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                  <Field
                    label={t('Key')}
                    hint={t('Canonical name, lowercase (e.g. sitting). This is the render and cache key.')}
                  >
                    <div style={{ display: 'flex', gap: 8 }}>
                      <input
                        className="ga-input"
                        value={draft.key}
                        disabled={!isNew}
                        onChange={(e) => upd('key', e.target.value)}
                      />
                      {!isNew && draft.renamable !== false ? (
                        <button className="ga-btn ga-btn-sm" style={{ whiteSpace: 'nowrap' }}
                          onClick={() => setRenameOpen(true)}>
                          {t('Rename key')}
                        </button>
                      ) : null}
                    </div>
                  </Field>

                <Field
                  label={isPose ? t('Pose text') : t('Expression text')}
                  hint={
                    isPose
                      ? t('Body posture for the image generation — arms, legs, posture. Third person, no names.')
                      : t('Facial expression for the image generation — brow, eyes, mouth. Third person, no names.')
                  }
                >
                  <textarea
                    className="ga-textarea"
                    rows={3}
                    value={draft.prompt}
                    onChange={(e) => upd('prompt', e.target.value)}
                  />
                </Field>

                <Field
                  label={t('Synonyms')}
                  hint={t('Comma-separated. Free text matching one of these lands on this key directly, without an embedding lookup.')}
                >
                  <CommaListInput
                    value={draft.synonyms}
                    onChange={(next) => upd('synonyms', next)}
                  />
                </Field>

                {!isPose && <Field label={t('Expression label')}>
                  <input className="ga-input" maxLength={80} value={draft.label || ''}
                    onChange={e => upd('label', e.target.value)} />
                </Field>}
                {isPose && <>
                  <Field label={t('Label (en)')}
                    hint={t('Gerund phrase, e.g. “dancing”. Empty = the key.')}>
                    <input className="ga-input" maxLength={80} value={draft.label || ''}
                      onChange={(e) => upd('label', e.target.value)} />
                  </Field>
                  <Field label={t('Label (de)')}
                    hint={t('Noun form, e.g. “Tanzen”. Used in German sentences.')}>
                    <input className="ga-input" maxLength={80} value={draft.label_de || ''}
                      onChange={(e) => upd('label_de', e.target.value)} />
                  </Field>
                </>}

                <Field
                  label={t('Stored in')}
                  hint={t('The shared catalog travels with the repository. Pick this'
                          + ' world for an entry that must never be committed —'
                          + ' a licensed or adult clip; it lives in the world.db. An'
                          + ' entry is only reachable in the game once it is in one of'
                          + ' the two, and the world layer wins over the shared file'
                          + ' for the same key.')}
                >
                  <select
                    className="ga-input"
                    value={draft.store || 'shared'}
                    onChange={(e) => upd('store', e.target.value as Store)}
                  >
                    <option value="shared">{t('shared catalog (committed)')}</option>
                    <option value="world">{t('this world (never committed)')}</option>
                  </select>
                </Field>

                {isPose ? (
                  <Field
                    label={t('Solo')}
                    hint={t('Off = the pose needs a second person (kissing, embracing). Those keys are skipped when a single-character image is rendered.')}
                  >
                    <label style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                      <input
                        type="checkbox"
                        checked={draft.solo !== false}
                        onChange={(e) => upd('solo', e.target.checked)}
                      />
                      <span>{t('Works with one character alone')}</span>
                    </label>
                  </Field>
                ) : null}

                </div>
                {isPose ? (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                    <Field
                      label={t('Animation')}
                      hint={t('Clip kind a 3D figure plays. Options come from the clips present in shared/models/clips.')}
                    >
                      <select
                        className="ga-input"
                        value={draft.animation}
                        onChange={(e) => {
                          const kind = e.target.value
                          // a pair clip has no solo half: the pose becomes a two-person one
                          setDraft((d) => (d ? { ...d, animation: kind,
                            solo: data.pair_kinds?.includes(kind) ? false : d.solo } : d))
                        }}
                      >
                        <option value="">{t('— pick a kind —')}</option>
                        {data.kinds.map((k) => (
                          <option key={k} value={k}>
                            {data.pair_kinds?.includes(k) ? `${k} — ${t('pair')}` : k}
                          </option>
                        ))}
                        {/* keep an animation whose clip has since been removed */}
                        {draft.animation && !data.kinds.includes(draft.animation) ? (
                          <option value={draft.animation}>
                            {draft.animation} ({t('no clip')})
                          </option>
                        ) : null}
                      </select>
                      {draft.solo !== false && (approveOf || !isNew) ? (
                        <button type="button" className="ga-btn ga-btn-sm"
                          disabled={animationJobs.some((job) => job.key === draft.key && activeJob(job))}
                          onClick={() => {
                            const entry = data.entries.find((item) => item.key === draft.key)
                            setAnimationDialog(approveOf
                              ? { mode: 'candidate', rawText: approveOf }
                              : { mode: 'entry', entryKey: draft.key, prompt: entry?.prompt || draft.prompt })
                          }}>
                          {approveOf ? t('Generate new') : draft.animation ? t('Regenerate') : t('Generate animation')}
                        </button>
                      ) : null}
                    </Field>
                    {/* Which figure sets actually have a file for the selected
                        kind — a kind that only exists as `female` leaves every
                        other figure standing. */}
                    {draft.animation ? (
                      <div className="ga-form-hint">
                        {t('Clip sets')}:{' '}
                        {(() => {
                          const cov = clipCoverage(clipList.clips, draft.animation)
                          return cov.length
                            ? cov.map((s) => setLabel(s, t)).join(' ')
                            : t('no clip')
                        })()}
                      </div>
                    ) : null}
                    {data.pair_kinds?.includes(draft.animation) ? (
                      <div className="ga-form-hint">
                        {t('Pair clip: two figures play its two halves together at one anchor — this pose needs a partner (Solo is off).')}
                      </div>
                    ) : null}
                    <Field
                      label={t('Place type')}
                      hint={t('The kind of marker this pose can be played on. Every pose belongs to exactly one place type.')}
                    >
                      <select
                        className="ga-input"
                        value={draft.group || ''}
                        onChange={(e) => upd('group', e.target.value)}
                      >
                        <option value="">{t('— pick a place type —')}</option>
                        {Object.entries(data.groups || {}).map(([key, g]) => (
                          <option key={key} value={key}>
                            {g.label ? `${g.label} (${key})` : key}
                          </option>
                        ))}
                        {/* keep a place type that has since been removed visible */}
                        {draft.group && !(data.groups || {})[draft.group] ? (
                          <option value={draft.group}>
                            {draft.group} ({t('unknown')})
                          </option>
                        ) : null}
                      </select>
                    </Field>

                    {draft.solo === false ? (
                      <div className="ga-form-row">
                        <Field
                          label={t('Places')}
                          hint={(() => {
                            const span = data.pair_spans?.[draft.animation]
                            if (typeof span !== 'number') {
                              return t('How many slots of the anchor marker the pair uses. A slot is 0.60 m — one body width.')
                            }
                            return t('The clip measures {span} m between the two figures; a slot is 0.60 m. That is the space they STAND in, not the floor the pose sweeps — a dance needs two slots however close the dancers are.')
                              .replace('{span}', span.toFixed(2))
                          })()}
                        >
                          <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
                            {([1, 2] as const).map((n) => (
                              <label
                                key={n}
                                style={{ display: 'flex', gap: 4, alignItems: 'center' }}
                              >
                                <input
                                  type="radio"
                                  name="pose-places"
                                  checked={draft.places === n}
                                  onChange={() => upd('places', n)}
                                />
                                <span>{n}</span>
                                {suggestedPlaces(data.pair_spans?.[draft.animation]) === n && (
                                  <span style={{ opacity: 0.6, fontSize: '0.8em' }}>
                                    {t('(measured)')}
                                  </span>
                                )}
                              </label>
                            ))}
                            {draft.places !== 1 && draft.places !== 2 && (
                              <span style={{ color: '#d6b06a', fontSize: '0.82em' }}>
                                {t('Please choose — a pair pose has no sensible default.')}
                              </span>
                            )}
                          </div>
                        </Field>
                        {/* The yaw offset is dialled UNDER THE PREVIEW, against
                            the virtual marker the pair sits on — one control,
                            where the effect is visible. Only a pose without an
                            animation (and so without a preview) keeps the plain
                            field here, so the value stays editable. */}
                        {draft.animation ? null : (
                          <Field
                            label={t('Yaw offset')}
                            hint={t('Degrees the pair clip’s frame turns against the marker facing.')}
                          >
                            <input
                              className="ga-input"
                              type="number"
                              min={-180}
                              max={180}
                              step={1}
                              value={draft.yaw_offset ?? 0}
                              onChange={(e) => upd('yaw_offset', Number(e.target.value))}
                            />
                            <span style={{ alignSelf: 'center' }}>°</span>
                          </Field>
                        )}
                      </div>
                    ) : null}

                    {/* Below the select, not inside the Field: .ga-field-control
                        is a flex ROW and would put the canvas beside the select.
                        A PAIR is previewed on a virtual marker of its place type
                        and carries the yaw dial; a solo pose never turns against
                        a marker, so it gets no `onYawOffset`. */}
                    {draft.animation ? (
                      <ClipPreview
                        kind={draft.animation}
                        bust={animationJobs.find((job) => job.key === draft.key && job.state === 'published')?.task_id}
                        height={360}
                        group={draft.group}
                        rootDrop={(data.groups || {})[draft.group || '']?.root_drop ?? 0}
                        yawOffset={draft.yaw_offset ?? 0}
                        onYawOffset={draft.solo === false
                          ? (deg) => upd('yaw_offset', deg)
                          : undefined}
                      />
                    ) : null}
                  </div>
                ) : null}
                {draft.movement && draft.deletable === false ? <div className="ga-form-hint">
                  {t('Movement poses are fixed: change their clip, but they cannot be deleted or renamed.')}
                </div> : null}
                {draft.is_default ? (
                  <div className="ga-form-hint">
                    {t('Default entry: every free text the catalog cannot absorb falls back to this key. It cannot be deleted.')}
                  </div>
                ) : null}
              </div>
            </>
          )}
        </section>
      </div>
      <ConfirmDialog open={pendingSet !== null} title={t('Discard unsaved changes?')}
        message={t('Switching expression sets discards the open entry draft.')}
        confirmLabel={t('Discard')}
        onConfirm={() => { if (pendingSet !== null) setExpressionSet(pendingSet); setPendingSet(null) }}
        onClose={() => setPendingSet(null)} />
      <ConfirmDialog open={deleteOpen} title={draft?.resettable ? t('Reset override') : t('Delete')}
        confirmLabel={draft?.resettable ? t('Reset override') : t('Delete')} danger
        message={[draft?.key || '', transitionCount
          ? t('Also removes {n} transition rule(s).').replace('{n}', String(transitionCount)) : '']
          .filter(Boolean).join(' · ')}
        onConfirm={() => { void remove() }} onClose={() => setDeleteOpen(false)} />
      <PromptDialog
        open={renameOpen}
        title={isPose ? t('Rename pose key') : t('Rename expression key')}
        label={t('New key')}
        message={t('Every stored reference in this world follows the new key. Other worlds keep the old key and fall back to the default pose there.')}
        initialValue={draft?.key || ''}
        confirmLabel={t('Rename')}
        onSubmit={(v) => { void renameKey(v) }}
        onClose={() => setRenameOpen(false)}
      />
      {animationDialog ? (
        <PoseAnimationDialog open {...animationDialog} onClose={closeAnimationDialog}
          onStarted={animationStarted} />
      ) : null}
      {choiceJob ? (
        <PoseAnimationChoice taskId={choiceJob.task_id} poseKey={choiceJob.key}
          generator={choiceJob.generator} candidates={choiceJob.candidates || []}
          onClose={() => setChoiceJob(null)}
          onDecided={(kind) => {
            const decided = choiceJob
            setChoiceJob(null)
            setJobsRefresh((value) => value + 1)
            void reloadLibrary()
            if (kind && axis === 'pose') {
              setDraft((current) => current && current.key === decided.key
                ? { ...current, animation: kind } : current)
            }
          }} />
      ) : null}
    </div>
  )
}
